input.content:
:root {
  --voltage-black: #0D0D0D;
  --backstage-charcoal: #1E1E2A;
  --reactor-yellow: #FFE600;
  --plasma-magenta: #FF1F8E;
  --ignition-orange: #FF5C00;
  --circuit-cyan: #00E5FF;
  --poster-cream: #F5F0DC;
  --crowd-white: #FFFFFF;

  --font-heading: 'Archivo Black', 'Arial Black', sans-serif;
  --font-body: 'Archivo', 'Helvetica Neue', Arial, sans-serif;
  --font-accent: 'Bebas Neue', 'Oswald', 'Arial Narrow', sans-serif;

  --container-max: 1280px;
  --container-pad-x: 48px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  width: 100%;
  overflow-x: hidden;
}

body {
  font-family: var(--font-body);
  background: var(--voltage-black);
  color: var(--crowd-white);
  font-size: 17px;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: var(--font-heading);
  cursor: pointer;
  border: none;
  background: none;
}

img, svg {
  display: block;
  max-width: 100%;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: -0.02em;
  line-height: 1.0;
}

.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding-left: var(--container-pad-x);
  padding-right: var(--container-pad-x);
}

.eyebrow {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  display: inline-block;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 15px;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  padding: 18px 32px;
  border-radius: 0;
  border: 2px solid transparent;
  transition: background 0.25s ease, color 0.25s ease, border-color 0.25s ease, transform 0.25s ease;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.btn-primary {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
  border-color: var(--reactor-yellow);
}

.btn-primary:hover {
  background: var(--plasma-magenta);
  border-color: var(--plasma-magenta);
  color: var(--voltage-black);
  transform: translateY(-2px);
}

.btn-secondary {
  background: transparent;
  color: var(--crowd-white);
  border-color: var(--crowd-white);
}

.btn-secondary:hover {
  background: transparent;
  color: var(--reactor-yellow);
  border-color: var(--reactor-yellow);
  transform: translateY(-2px);
}

.btn-outline-yellow {
  background: transparent;
  border-color: var(--reactor-yellow);
  color: var(--reactor-yellow);
}

.btn-outline-yellow:hover {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
  transform: translateY(-2px);
}

.btn-dark {
  background: var(--voltage-black);
  color: var(--reactor-yellow);
  border-color: var(--voltage-black);
}

.btn-dark:hover {
  background: var(--plasma-magenta);
  color: var(--crowd-white);
  border-color: var(--plasma-magenta);
  transform: translateY(-2px);
}

.btn-outline-black {
  background: transparent;
  border-color: var(--voltage-black);
  color: var(--voltage-black);
}

.btn-outline-black:hover {
  background: var(--voltage-black);
  color: var(--reactor-yellow);
  transform: translateY(-2px);
}

/* Reveal animations */
.reveal {
  opacity: 0;
  transform: translateY(32px);
  transition: opacity 0.8s ease, transform 0.8s ease;
}

.reveal.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.reveal-stagger > * {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}

.reveal-stagger.is-visible > * {
  opacity: 1;
  transform: translateY(0);
}

.reveal-stagger.is-visible > *:nth-child(1) { transition-delay: 0.04s; }
.reveal-stagger.is-visible > *:nth-child(2) { transition-delay: 0.12s; }
.reveal-stagger.is-visible > *:nth-child(3) { transition-delay: 0.2s; }
.reveal-stagger.is-visible > *:nth-child(4) { transition-delay: 0.28s; }
.reveal-stagger.is-visible > *:nth-child(5) { transition-delay: 0.36s; }
.reveal-stagger.is-visible > *:nth-child(6) { transition-delay: 0.44s; }

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(255, 230, 0, 0.5); }
  50% { box-shadow: 0 0 0 12px rgba(255, 230, 0, 0); }
}

@keyframes pulse-glow-magenta {
  0%, 100% { box-shadow: 0 0 0 0 rgba(255, 31, 142, 0.45); }
  50% { box-shadow: 0 0 0 14px rgba(255, 31, 142, 0); }
}

@keyframes float-bolt {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-12px) rotate(2deg); }
}

@keyframes spark-fly {
  0% { transform: translate(0, 0) scale(0.6); opacity: 0; }
  20% { opacity: 1; }
  100% { transform: translate(var(--dx, 0), var(--dy, -120px)) scale(0); opacity: 0; }
}

@keyframes marquee-slide {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes count-up {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes word-reveal {
  0% { opacity: 0; transform: translateY(40px) scale(0.92); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes underline-grow {
  from { width: 0; }
  to { width: 100%; }
}

@keyframes electric-pulse {
  0%, 100% { opacity: 0.18; }
  50% { opacity: 0.32; }
}

@keyframes rotate-slow {
  from { transform: rotate(0); }
  to { transform: rotate(360deg); }
}

@keyframes scan-line {
  0% { transform: translateY(-100%); }
  100% { transform: translateY(100%); }
}

@keyframes bar-grow {
  from { transform: scaleX(0); }
  to { transform: scaleX(var(--bar-scale, 1)); }
}

.is-visible .anim-bar {
  animation: bar-grow 1.4s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: left center;
}

section {
  position: relative;
}

::selection {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
}

