import { useEffect, useState } from 'react';
import './Nav.css';

const links = [
  { href: 'index.html', label: 'Home', slug: 'home' },
  { href: 'about.html', label: 'About', slug: 'about' },
  { href: 'departments.html', label: 'Departments', slug: 'departments' },
  { href: 'research.html', label: 'Research', slug: 'research' },
  { href: 'contact.html', label: 'Contact', slug: 'contact' },
];

export default function Nav({ active }) {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 16);
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`site-nav ${scrolled ? 'is-scrolled' : ''}`}>
      <div className="site-nav__inner">
        <a className="site-nav__brand" href="index.html" aria-label="BoltWorks home">
          <svg width="32" height="32" viewBox="0 0 32 32" aria-hidden="true">
            <path d="M14 2 L4 18 L13 18 L10 30 L28 12 L19 12 L22 2 Z" fill="#FFE600" stroke="#0D0D0D" strokeWidth="1.5" strokeLinejoin="round" />
          </svg>
          <span className="site-nav__wordmark">BOLT<span className="site-nav__wordmark-accent">WORKS</span></span>
        </a>

        <button
          className={`site-nav__toggle ${open ? 'is-open' : ''}`}
          aria-label="Toggle navigation"
          aria-expanded={open}
          onClick={() => setOpen((v) => !v)}
        >
          <span /><span /><span />
        </button>

        <nav className={`site-nav__links ${open ? 'is-open' : ''}`}>
          {links.map((l) => (
            <a
              key={l.slug}
              href={l.href}
              className={`site-nav__link ${active === l.slug ? 'is-active' : ''}`}
            >
              {l.label}
            </a>
          ))}
          <a className="site-nav__cta" href="contact.html">Join the Club</a>
        </nav>
      </div>
    </header>
  );
}

