input.content:
.site-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: rgba(13, 13, 13, 0.45);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-bottom: 1px solid transparent;
  transition: background 0.3s ease, border-color 0.3s ease;
}

.site-nav.is-scrolled {
  background: rgba(13, 13, 13, 0.92);
  border-bottom-color: rgba(255, 230, 0, 0.15);
}

.site-nav__inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 18px 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.site-nav__brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-size: 20px;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--crowd-white);
}

.site-nav__brand svg {
  animation: float-bolt 3.2s ease-in-out infinite;
}

.site-nav__wordmark-accent {
  color: var(--reactor-yellow);
}

.site-nav__links {
  display: flex;
  align-items: center;
  gap: 8px;
}

.site-nav__link {
  font-family: var(--font-accent);
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--poster-cream);
  padding: 10px 14px;
  position: relative;
  transition: color 0.2s ease;
}

.site-nav__link::after {
  content: '';
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 4px;
  height: 2px;
  background: var(--reactor-yellow);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.25s ease;
}

.site-nav__link:hover {
  color: var(--reactor-yellow);
}

.site-nav__link:hover::after,
.site-nav__link.is-active::after {
  transform: scaleX(1);
}

.site-nav__link.is-active {
  color: var(--reactor-yellow);
}

.site-nav__cta {
  font-family: var(--font-heading);
  font-size: 13px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  background: var(--reactor-yellow);
  color: var(--voltage-black);
  padding: 12px 22px;
  margin-left: 12px;
  transition: background 0.25s ease, color 0.25s ease, transform 0.25s ease;
}

.site-nav__cta:hover {
  background: var(--plasma-magenta);
  color: var(--crowd-white);
  transform: translateY(-2px);
}

.site-nav__toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.site-nav__toggle span {
  display: block;
  width: 26px;
  height: 3px;
  background: var(--crowd-white);
  transition: transform 0.25s ease, opacity 0.2s ease;
}

.site-nav__toggle.is-open span:nth-child(1) { transform: translateY(8px) rotate(45deg); }
.site-nav__toggle.is-open span:nth-child(2) { opacity: 0; }
.site-nav__toggle.is-open span:nth-child(3) { transform: translateY(-8px) rotate(-45deg); }

@media (max-width: 900px) {
  .site-nav__inner { padding: 14px 24px; }
  .site-nav__toggle { display: flex; }
  .site-nav__links {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--voltage-black);
    border-bottom: 2px solid var(--reactor-yellow);
    flex-direction: column;
    padding: 16px 24px;
    gap: 4px;
    align-items: stretch;
    transform: translateY(-12px);
    opacity: 0;
    pointer-events: none;
    transition: transform 0.25s ease, opacity 0.25s ease;
  }
  .site-nav__links.is-open {
    transform: translateY(0);
    opacity: 1;
    pointer-events: auto;
  }
  .site-nav__link { padding: 12px 0; font-size: 16px; }
  .site-nav__cta { margin: 8px 0 0; text-align: center; }
}

