}

@keyframes hero-blink {
  0%, 100% { fill: #FF1F8E; r: 14; }
  50% { fill: #FFE600; r: 16; }
}

.hero-eye {
  animation: hero-eye-pulse 2s ease-in-out infinite;
}
.hero-eye--l { animation-delay: 0s; }
.hero-eye--r { animation-delay: 0.2s; }

@keyframes hero-eye-pulse {
  0%, 100% { fill: #00E5FF; }
  50% { fill: #FFE600; }
}

.hero-reactor {
  animation: hero-reactor-pulse 2.4s ease-in-out infinite;
  transform-origin: 300px 440px;
}

@keyframes hero-reactor-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.08); }
}

.hero-led {
  animation: hero-led-blink 1.4s ease-in-out infinite;
}
.hero-led--1 { animation-delay: 0s; }
.hero-led--2 { animation-delay: 0.2s; }
.hero-led--3 { animation-delay: 0.4s; }
.hero-led--4 { animation-delay: 0.6s; }
.hero-led--5 { animation-delay: 0.8s; }
.hero-led--6 { animation-delay: 1s; }

@keyframes hero-led-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

.hero-sparks circle {
  animation: spark-twinkle 2.6s ease-in-out infinite;
}
.hero-sparks circle:nth-child(2) { animation-delay: 0.4s; }
.hero-sparks circle:nth-child(3) { animation-delay: 0.8s; }
.hero-sparks circle:nth-child(4) { animation-delay: 1.2s; }
.hero-sparks circle:nth-child(5) { animation-delay: 1.6s; }

@keyframes spark-twinkle {
  0%, 100% { opacity: 0.4; transform: scale(0.7); }
  50% { opacity: 1; transform: scale(1.4); }
}

/* Circuit pattern */
.circuit-pattern-svg {
  width: 100%;
  height: 100%;
  position: absolute;
  inset: 0;
  opacity: 0.12;
  pointer-events: none;
}

/* Garage SVG */
.garage-svg { width: 100%; height: auto; }
.garage-gear--big > g {
  animation: rotate-slow 12s linear infinite;
  transform-origin: 0 0;
}
.garage-gear--small > g {
  animation: rotate-slow 8s linear infinite reverse;
  transform-origin: 0 0;
}
.garage-sparks path { animation: spark-twinkle 2s ease-in-out infinite; }
.garage-sparks path:nth-child(2) { animation-delay: 0.3s; }
.garage-sparks path:nth-child(3) { animation-delay: 0.6s; }

/* Department icons */
.dept-icon { width: 100%; height: 100%; }

/* Robot arm */
.arm-svg { width: 100%; height: auto; overflow: visible; }
.arm-bulb {
  transform-origin: 380px 180px;
  animation: arm-bulb-glow 2s ease-in-out infinite;
}
@keyframes arm-bulb-glow {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.05); }
}
.arm-bulb-rays {
  animation: electric-pulse 2s ease-in-out infinite;
}
.arm-sparks circle { animation: spark-twinkle 2s ease-in-out infinite; }
.arm-sparks circle:nth-child(2) { animation-delay: 0.4s; }
.arm-sparks circle:nth-child(3) { animation-delay: 0.8s; }

/* Handshake */
.handshake-svg { width: 100%; height: auto; }
.hs-bolt-main {
  transform-origin: 295px 155px;
  animation: hero-blink 1.5s ease-in-out infinite;
}
.hs-sparks circle { animation: spark-twinkle 2.2s ease-in-out infinite; }
.hs-sparks circle:nth-child(3) { animation-delay: 0.3s; }
.hs-sparks circle:nth-child(4) { animation-delay: 0.6s; }
.hs-sparks circle:nth-child(5) { animation-delay: 0.9s; }
.hs-sparks circle:nth-child(6) { animation-delay: 1.2s; }
.hs-sparks circle:nth-child(7) { animation-delay: 1.5s; }

/* Map */
.map-svg { width: 100%; height: 100%; display: block; }
.map-marker {
  transform-origin: 510px 200px;
  animation: float-bolt 3s ease-in-out infinite;
}
.map-pulse {
  transform-origin: 510px 100px;
  animation: map-pulse 2.4s ease-out infinite;
}
@keyframes map-pulse {
  0% { r: 30; opacity: 0.8; }
  100% { r: 80; opacity: 0; }
}

.wristband-svg { width: 100%; height: auto; }

