input.content:
/* ============ HERO ============ */
.hero {
  position: relative;
  background: var(--voltage-black);
  min-height: 100vh;
  padding-top: 96px;
  padding-bottom: 88px;
  overflow: hidden;
}

.hero__bg-glow {
  position: absolute;
  top: -20%;
  right: -15%;
  width: 70%;
  height: 90%;
  background: radial-gradient(circle, rgba(255, 31, 142, 0.18) 0%, rgba(255, 230, 0, 0.06) 35%, transparent 65%);
  pointer-events: none;
  animation: electric-pulse 4s ease-in-out infinite;
}

.hero__grid {
  position: relative;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 40px 48px 0;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 40px;
  align-items: center;
  min-height: calc(100vh - 200px);
  z-index: 2;
}

.hero__copy {
  position: relative;
}

.hero__eyebrow {
  color: var(--plasma-magenta);
  margin-bottom: 18px;
  opacity: 0;
  animation: word-reveal 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards 0.1s;
}

.hero__headline {
  font-family: var(--font-heading);
  font-size: clamp(56px, 9vw, 104px);
  line-height: 0.92;
  letter-spacing: -0.035em;
  margin-bottom: 28px;
}

.hero__headline .hero__word {
  display: block;
  color: var(--crowd-white);
  opacity: 0;
  transform: translateY(40px) scale(0.96);
  animation: word-reveal 0.85s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.hero__word--1 { animation-delay: 0.25s; }
.hero__word--2 { animation-delay: 0.5s; }
.hero__word--3 {
  animation-delay: 0.75s;
  color: var(--reactor-yellow);
  position: relative;
  text-shadow: 0 0 30px rgba(255, 230, 0, 0.4);
}
.hero__word--3::after {
  content: '';
  position: absolute;
  bottom: 6px;
  left: 0;
  height: 6px;
  width: 0;
  background: var(--plasma-magenta);
  animation: underline-grow 0.8s ease forwards 1.5s;
}

.hero__subhead {
  font-family: var(--font-heading);
  text-transform: uppercase;
  font-size: clamp(18px, 1.8vw, 22px);
  color: var(--crowd-white);
  margin-bottom: 22px;
  letter-spacing: -0.01em;
  opacity: 0;
  animation: word-reveal 0.8s ease forwards 1s;
}

.hero__body {
  color: var(--poster-cream);
  max-width: 520px;
  font-size: 17px;
  margin-bottom: 36px;
  opacity: 0;
  animation: word-reveal 0.8s ease forwards 1.15s;
}

.hero__ctas {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  opacity: 0;
  animation: word-reveal 0.8s ease forwards 1.3s;
}

.hero__cta-primary {
  animation: pulse-glow 2.4s ease-in-out infinite 2s;
}

.hero__art {
  position: relative;
  display: flex;
  justify-content: flex-end;
  margin-right: -10%;
  margin-bottom: -80px;
  z-index: 3;
  opacity: 0;
  animation: word-reveal 1.1s cubic-bezier(0.22, 1, 0.36, 1) forwards 0.5s;
}

.hero__art .hero-robot-svg {
  max-width: 640px;
  width: 100%;
  filter: drop-shadow(0 30px 60px rgba(255, 31, 142, 0.25));
}

/* Marquee */
.hero__marquee {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: var(--reactor-yellow);
  color: var(--voltage-black);
  overflow: hidden;
  display: flex;
  align-items: center;
  border-top: 2px solid var(--voltage-black);
  border-bottom: 2px solid var(--voltage-black);
}

.hero__marquee-track {
  display: flex;
  white-space: nowrap;
  animation: marquee-slide 28s linear infinite;
  font-family: var(--font-accent);
  font-size: 14px;
  letter-spacing: 0.25em;
  text-transform: uppercase;
}

.hero__marquee-group {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 0 24px;
}

.hero__marquee-dot {
  width: 6px;
  height: 6px;
  background: var(--voltage-black);
  border-radius: 50%;
  display: inline-block;
}

/* ============ STATS BAND ============ */
.stats-band {
  background: var(--backstage-charcoal);
  padding: 56px 0 0;
  position: relative;
}

.stats-band__head {
  text-align: center;
  margin-bottom: 44px;
}

.stats-band__eyebrow {
  color: var(--circuit-cyan);
  margin-bottom: 14px;
}

.stats-band__headline {
  font-size: clamp(24px, 3.2vw, 30px);
  color: var(--crowd-white);
}

.stats-band__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  padding-bottom: 56px;
}

.stat-cell {
  text-align: left;
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.7s ease, transform 0.7s ease;
  transition-delay: var(--stat-delay, 0s);
}

.stat-cell.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.stat-cell__numeral {
  font-family: var(--font-heading);
  font-size: clamp(56px, 8vw, 96px);
  color: var(--reactor-yellow);
  letter-spacing: -0.04em;
  line-height: 1;
  margin-bottom: 12px;
  text-shadow: 0 0 24px rgba(255, 230, 0, 0.18);
}

.stat-cell__desc {
  color: var(--poster-cream);
  font-size: 15px;
  max-width: 200px;
}

.stats-band__rule {
  height: 2px;
  background: var(--ignition-orange);
  width: 100%;
}

/* ============ FEATURE GRID ============ */
.features {
  background: var(--voltage-black);
  padding: 96px 0;
}

.features__head { margin-bottom: 48px; }

.features__eyebrow {
  color: var(--plasma-magenta);
  margin-bottom: 14px;
}

.features__headline {
  font-size: clamp(32px, 5vw, 60px);
  color: var(--crowd-white);
  max-width: 760px;
  margin-bottom: 18px;
}

.features__subhead {
  color: var(--poster-cream);
  font-size: 18px;
  max-width: 600px;
}

.features__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-bottom: 48px;
}

.feature-card {
  background: var(--backstage-charcoal);
  padding: 32px;
  position: relative;
  overflow: hidden;
  transition: background 0.3s ease, transform 0.3s ease;
}

.feature-card__top {
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--accent);
  transition: height 0.3s ease;
}

.feature-card:hover { background: #25252F; transform: translateY(-4px); }
.feature-card:hover .feature-card__top { height: 6px; }
.feature-card:hover .feature-card__arrow { color: var(--accent); transform: translateX(6px); }

.feature-card__tag {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.22em;
  color: var(--accent);
  text-transform: uppercase;
  display: inline-block;
  border: 1px solid var(--accent);
  padding: 4px 10px;
  margin-bottom: 14px;
}

.feature-card__title {
  font-size: 24px;
  color: var(--crowd-white);
  margin-bottom: 14px;
}

.feature-card__body {
  color: var(--poster-cream);
  font-size: 16px;
}

.feature-card__arrow {
  position: absolute;
  bottom: 24px;
  right: 28px;
  color: var(--poster-cream);
  opacity: 0.6;
  transition: color 0.25s ease, transform 0.25s ease;
}

.features__cta { margin-top: 8px; }

/* ============ TIMELINE ============ */
.timeline {
  background: var(--voltage-black);
  padding: 96px 0;
  position: relative;
}

.timeline__head {
  text-align: center;
  margin-bottom: 60px;
}

.timeline__eyebrow {
  color: var(--ignition-orange);
  margin-bottom: 14px;
}

.timeline__headline {
  font-size: clamp(32px, 5vw, 60px);
  color: var(--crowd-white);
}

.timeline__subhead {
  color: var(--poster-cream);
  font-size: 18px;
  max-width: 560px;
  margin: 16px auto 0;
}

.timeline__spine {
  position: absolute;
  left: 50%;
  top: 220px;
  bottom: 140px;
  width: 3px;
  background: var(--ignition-orange);
  transform: translateX(-50%);
}

.timeline__list {
  list-style: none;
  position: relative;
  padding: 0;
  margin: 0;
}

.timeline-node {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
  margin-bottom: 64px;
  opacity: 0;
  transform: translateY(40px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}

.timeline-node.is-visible { opacity: 1; transform: translateY(0); }

.timeline-node__badge {
  width: 88px;
  height: 88px;
  border-radius: 50%;
  background: var(--ignition-orange);
  color: var(--voltage-black);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-accent);
  font-size: 16px;
  letter-spacing: 0.1em;
  text-align: center;
  box-shadow: 0 0 0 6px var(--voltage-black);
  position: relative;
  z-index: 2;
  transition: transform 0.4s ease;
}

.timeline-node__badge::before {
  content: '';
  position: absolute;
  inset: -10px;
  border-radius: 50%;
  border: 2px dashed rgba(255, 92, 0, 0.4);
  animation: rotate-slow 14s linear infinite;
}

.timeline-node.is-visible .timeline-node__badge { transform: scale(1); }

.timeline-node__content {
  background: rgba(30, 30, 42, 0.5);
  padding: 24px;
  border-left: 3px solid var(--ignition-orange);
  max-width: 380px;
}

.timeline-node--left .timeline-node__content {
  grid-column: 1;
  text-align: right;
  border-left: none;
  border-right: 3px solid var(--ignition-orange);
  justify-self: end;
}

.timeline-node--right .timeline-node__content {
  grid-column: 3;
  justify-self: start;
}

.timeline-node--left .timeline-node__badge { grid-column: 2; }
.timeline-node--right .timeline-node__badge { grid-column: 2; }

.timeline-node__title {
  font-size: 22px;
  color: var(--crowd-white);
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.timeline-node__body {
  color: var(--poster-cream);
  font-size: 16px;
}

.timeline__cta {
  text-align: center;
  margin-top: 24px;
}

/* ============ CTA YELLOW CLOSE ============ */
.cta-yellow {
  background: var(--reactor-yellow);
  padding: 110px 32px;
  position: relative;
  overflow: hidden;
  text-align: center;
}

.cta-yellow__pattern {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 1;
}

.cta-yellow__sparks {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.cta-yellow__bolt {
  position: absolute;
  opacity: 0.65;
}

.cta-yellow__bolt--l {
  left: 6%;
  top: 50%;
  transform: translateY(-50%) rotate(-12deg);
  animation: float-bolt 4s ease-in-out infinite;
}

.cta-yellow__bolt--r {
  right: 8%;
  top: 50%;
  transform: translateY(-50%) rotate(15deg);
  animation: float-bolt 3.4s ease-in-out infinite 0.5s;
}

.cta-yellow__inner {
  position: relative;
  max-width: 880px;
  margin: 0 auto;
}

.cta-yellow__eyebrow {
  color: rgba(13, 13, 13, 0.7);
  margin-bottom: 18px;
}

.cta-yellow__headline {
  font-size: clamp(40px, 6.5vw, 84px);
  color: var(--voltage-black);
  letter-spacing: -0.03em;
  line-height: 0.92;
  margin-bottom: 22px;
}

.cta-yellow__subhead {
  font-family: var(--font-heading);
  font-size: clamp(18px, 2vw, 22px);
  color: var(--voltage-black);
  letter-spacing: -0.01em;
  text-transform: uppercase;
  opacity: 0.85;
  margin-bottom: 36px;
}

.cta-yellow__ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ============ RESPONSIVE ============ */
@media (max-width: 1100px) {
  .hero__grid { grid-template-columns: 1fr; padding-top: 60px; }
  .hero__art { margin: 24px 0 0; justify-content: center; }
  .timeline__spine { display: none; }
  .timeline-node { grid-template-columns: auto 1fr; gap: 18px; }
  .timeline-node--left .timeline-node__content,
  .timeline-node--right .timeline-node__content {
    grid-column: 2;
    text-align: left;
    border-right: none;
    border-left: 3px solid var(--ignition-orange);
    justify-self: start;
  }
  .timeline-node--left .timeline-node__badge,
  .timeline-node--right .timeline-node__badge { grid-column: 1; width: 72px; height: 72px; font-size: 13px; }
}

@media (max-width: 768px) {
  .hero { padding-top: 80px; }
  .hero__grid { padding: 0 24px; }
  .stats-band__grid { grid-template-columns: 1fr 1fr; gap: 24px; }
  .features { padding: 72px 0; }
  .features__grid { grid-template-columns: 1fr; }
  .cta-yellow { padding: 80px 20px; }
  .cta-yellow__bolt { display: none; }
}

@media (max-width: 480px) {
  .stat-cell__desc { font-size: 13px; }
  .feature-card { padding: 24px; }
}

tool_use_result.content:
/* ============ HERO ============ */
.hero {
  position: relative;
  background: var(--voltage-black);
  min-height: 100vh;
  padding-top: 96px;
  padding-bottom: 88px;
  overflow: hidden;
}

.hero__bg-glow {
  position: absolute;
  top: -20%;
  right: -15%;
  width: 70%;
  height: 90%;
  background: radial-gradient(circle, rgba(255, 31, 142, 0.18) 0%, rgba(255, 230, 0, 0.06) 35%, transparent 65%);
  pointer-events: none;
  animation: electric-pulse 4s ease-in-out infinite;
}

.hero__grid {
  position: relative;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 40px 48px 0;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 40px;
  align-items: center;
  min-height: calc(100vh - 200px);
  z-index: 2;
}

.hero__copy {
  position: relative;
}

.hero__eyebrow {
  color: var(--plasma-magenta);
  margin-bottom: 18px;
  opacity: 0;
  animation: word-reveal 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards 0.1s;
}

.hero__headline {
  font-family: var(--font-heading);
  font-size: clamp(56px, 9vw, 104px);
  line-height: 0.92;
  letter-spacing: -0.035em;
  margin-bottom: 28px;
}

.hero__headline .hero__word {
  display: block;
  color: var(--crowd-white);
  opacity: 0;
  transform: translateY(40px) scale(0.96);
  animation: word-reveal 0.85s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.hero__word--1 { animation-delay: 0.25s; }
.hero__word--2 { animation-delay: 0.5s; }
.hero__word--3 {
  animation-delay: 0.75s;
  color: var(--reactor-yellow);
  position: relative;
  text-shadow: 0 0 30px rgba(255, 230, 0, 0.4);
}
.hero__word--3::after {
  content: '';
  position: absolute;
  bottom: 6px;
  left: 0;
  height: 6px;
  width: 0;
  background: var(--plasma-magenta);
  animation: underline-grow 0.8s ease forwards 1.5s;
}

.hero__subhead {
  font-family: var(--font-heading);
  text-transform: uppercase;
  font-size: clamp(18px, 1.8vw, 22px);
  color: var(--crowd-white);
  margin-bottom: 22px;
  letter-spacing: -0.01em;
  opacity: 0;
  animation: word-reveal 0.8s ease forwards 1s;
}

.hero__body {
  color: var(--poster-cream);
  max-width: 520px;
  font-size: 17px;
  margin-bottom: 36px;
  opacity: 0;
  animation: word-reveal 0.8s ease forwards 1.15s;
}

.hero__ctas {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  opacity: 0;
  animation: word-reveal 0.8s ease forwards 1.3s;
}

.hero__cta-primary {
  animation: pulse-glow 2.4s ease-in-out infinite 2s;
}

.hero__art {
  position: relative;
  display: flex;
  justify-content: flex-end;
  margin-right: -10%;
  margin-bottom: -80px;
  z-index: 3;
  opacity: 0;
  animation: word-reveal 1.1s cubic-bezier(0.22, 1, 0.36, 1) forwards 0.5s;
}

.hero__art .hero-robot-svg {
  max-width: 640px;
  width: 100%;
  filter: drop-shadow(0 30px 60px rgba(255, 31, 142, 0.25));
}

/* Marquee */
.hero__marquee {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: var(--reactor-yellow);
  color: var(--voltage-black);
  overflow: hidden;
  display: flex;
  align-items: center;
  border-top: 2px solid var(--voltage-black);
  border-bottom: 2px solid var(--voltage-black);
}

.hero__marquee-track {
  display: flex;
  white-space: nowrap;
  animation: marquee-slide 28s linear infinite;
  font-family: var(--font-accent);
  font-size: 14px;
  letter-spacing: 0.25em;
  text-transform: uppercase;
}

.hero__marquee-group {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 0 24px;
}

.hero__marquee-dot {
  width: 6px;
  height: 6px;
  background: var(--voltage-black);
  border-radius: 50%;
  display: inline-block;
}

/* ============ STATS BAND ============ */
.stats-band {
  background: var(--backstage-charcoal);
  padding: 56px 0 0;
  position: relative;
}

.stats-band__head {
  text-align: center;
  margin-bottom: 44px;
}

.stats-band__eyebrow {
  color: var(--circuit-cyan);
  margin-bottom: 14px;
}

.stats-band__headline {
  font-size: clamp(24px, 3.2vw, 30px);
  color: var(--crowd-white);
}

.stats-band__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  padding-bottom: 56px;
}

.stat-cell {
  text-align: left;
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.7s ease, transform 0.7s ease;
  transition-delay: var(--stat-delay, 0s);
}

.stat-cell.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.stat-cell__numeral {
  font-family: var(--font-heading);
  font-size: clamp(56px, 8vw, 96px);
  color: var(--reactor-yellow);
  letter-spacing: -0.04em;
  line-height: 1;
  margin-bottom: 12px;
  text-shadow: 0 0 24px rgba(255, 230, 0, 0.18);
}

.stat-cell__desc {
  color: var(--poster-cream);
  font-size: 15px;
  max-width: 200px;
}

.stats-band__rule {
  height: 2px;
  background: var(--ignition-orange);
  width: 100%;
}

/* ============ FEATURE GRID ============ */
.features {
  background: var(--voltage-black);
  padding: 96px 0;
}

.features__head { margin-bottom: 48px; }

.features__eyebrow {
  color: var(--plasma-magenta);
  margin-bottom: 14px;
}

.features__headline {
  font-size: clamp(32px, 5vw, 60px);
  color: var(--crowd-white);
  max-width: 760px;
  margin-bottom: 18px;
}

.features__subhead {
  color: var(--poster-cream);
  font-size: 18px;
  max-width: 600px;
}

.features__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-bottom: 48px;
}

.feature-card {
  background: var(--backstage-charcoal);
  padding: 32px;
  position: relative;
  overflow: hidden;
  transition: background 0.3s ease, transform 0.3s ease;
}

.feature-card__top {
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--accent);
  transition: height 0.3s ease;
}

.feature-card:hover { background: #25252F; transform: translateY(-4px); }
.feature-card:hover .feature-card__top { height: 6px; }
.feature-card:hover .feature-card__arrow { color: var(--accent); transform: translateX(6px); }

.feature-card__tag {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.22em;
  color: var(--accent);
  text-transform: uppercase;
  display: inline-block;
  border: 1px solid var(--accent);
  padding: 4px 10px;
  margin-bottom: 14px;
}

.feature-card__title {
  font-size: 24px;
  color: var(--crowd-white);
  margin-bottom: 14px;
}

.feature-card__body {
  color: var(--poster-cream);
  font-size: 16px;
}

.feature-card__arrow {
  position: absolute;
  bottom: 24px;
  right: 28px;
  color: var(--poster-cream);
  opacity: 0.6;
  transition: color 0.25s ease, transform 0.25s ease;
}

.features__cta { margin-top: 8px; }

/* ============ TIMELINE ============ */
.timeline {
  background: var(--voltage-black);
  padding: 96px 0;
  position: relative;
}

.timeline__head {
  text-align: center;
  margin-bottom: 60px;
}

.timeline__eyebrow {
  color: var(--ignition-orange);
  margin-bottom: 14px;
}

.timeline__headline {
  font-size: clamp(32px, 5vw, 60px);
  color: var(--crowd-white);
}

.timeline__subhead {
  color: var(--poster-cream);
  font-size: 18px;
  max-width: 560px;
  margin: 16px auto 0;
}

.timeline__spine {
  position: absolute;
  left: 50%;
  top: 220px;
  bottom: 140px;
  width: 3px;
  background: var(--ignition-orange);
  transform: translateX(-50%);
}

.timeline__list {
  list-style: none;
  position: relative;
  padding: 0;
  margin: 0;
}

.timeline-node {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
  margin-bottom: 64px;
  opacity: 0;
  transform: translateY(40px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}

.timeline-node.is-visible { opacity: 1; transform: translateY(0); }

.timeline-node__badge {
  width: 88px;
  height: 88px;
  border-radius: 50%;
  background: var(--ignition-orange);
  color: var(--voltage-black);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-accent);
  font-size: 16px;
  letter-spacing: 0.1em;
  text-align: center;
  box-shadow: 0 0 0 6px var(--voltage-black);
  position: relative;
  z-index: 2;
  transition: transform 0.4s ease;
}

.timeline-node__badge::before {
  content: '';
  position: absolute;
  inset: -10px;
  border-radius: 50%;
  border: 2px dashed rgba(255, 92, 0, 0.4);
  animation: rotate-slow 14s linear infinite;
}

.timeline-node.is-visible .timeline-node__badge { transform: scale(1); }

.timeline-node__content {
  background: rgba(30, 30, 42, 0.5);
  padding: 24px;
  border-left: 3px solid var(--ignition-orange);
  max-width: 380px;
}

.timeline-node--left .timeline-node__content {
  grid-column: 1;
  text-align: right;
  border-left: none;
  border-right: 3px solid var(--ignition-orange);
  justify-self: end;
}

.timeline-node--right .timeline-node__content {
  grid-column: 3;
  justify-self: start;
}

.timeline-node--left .timeline-node__badge { grid-column: 2; }
.timeline-node--right .timeline-node__badge { grid-column: 2; }

.timeline-node__title {
  font-size: 22px;
  color: var(--crowd-white);
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.timeline-node__body {
  color: var(--poster-cream);
  font-size: 16px;
}

.timeline__cta {
  text-align: center;
  margin-top: 24px;
}

/* ============ CTA YELLOW CLOSE ============ */
.cta-yellow {
  background: var(--reactor-yellow);
  padding: 110px 32px;
  position: relative;
  overflow: hidden;
  text-align: center;
}

.cta-yellow__pattern {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 1;
}

.cta-yellow__sparks {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.cta-yellow__bolt {
  position: absolute;
  opacity: 0.65;
}

.cta-yellow__bolt--l {
  left: 6%;
  top: 50%;
  transform: translateY(-50%) rotate(-12deg);
  animation: float-bolt 4s ease-in-out infinite;
}

.cta-yellow__bolt--r {
  right: 8%;
  top: 50%;
  transform: translateY(-50%) rotate(15deg);
  animation: float-bolt 3.4s ease-in-out infinite 0.5s;
}

.cta-yellow__inner {
  position: relative;
  max-width: 880px;
  margin: 0 auto;
}

.cta-yellow__eyebrow {
  color: rgba(13, 13, 13, 0.7);
  margin-bottom: 18px;
}

.cta-yellow__headline {
  font-size: clamp(40px, 6.5vw, 84px);
  color: var(--voltage-black);
  letter-spacing: -0.03em;
  line-height: 0.92;
  margin-bottom: 22px;
}

.cta-yellow__subhead {
  font-family: var(--font-heading);
  font-size: clamp(18px, 2vw, 22px);
  color: var(--voltage-black);
  letter-spacing: -0.01em;
  text-transform: uppercase;
  opacity: 0.85;
  margin-bottom: 36px;
}

.cta-yellow__ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ============ RESPONSIVE ============ */
@media (max-width: 1100px) {
  .hero__grid { grid-template-columns: 1fr; padding-top: 60px; }
  .hero__art { margin: 24px 0 0; justify-content: center; }
  .timeline__spine { display: none; }
  .timeline-node { grid-template-columns: auto 1fr; gap: 18px; }
  .timeline-node--left .timeline-node__content,
  .timeline-node--right .timeline-node__content {
    grid-column: 2;
    text-align: left;
    border-right: none;
    border-left: 3px solid var(--ignition-orange);
    justify-self: start;
  }
  .timeline-node--left .timeline-node__badge,
  .timeline-node--right .timeline-node__badge { grid-column: 1; width: 72px; height: 72px; font-size: 13px; }
}

@media (max-width: 768px) {
  .hero { padding-top: 80px; }
  .hero__grid { padding: 0 24px; }
  .stats-band__grid { grid-template-columns: 1fr 1fr; gap: 24px; }
  .features { padding: 72px 0; }
  .features__grid { grid-template-columns: 1fr; }
  .cta-yellow { padding: 80px 20px; }
  .cta-yellow__bolt { display: none; }
}

@media (max-width: 480px) {
  .stat-cell__desc { font-size: 13px; }
  .feature-card { padding: 24px; }
}

input.content:
import React from 'react';
import ReactDOM from 'react-dom/client';
import Nav from '../components/Nav.jsx';
import Footer from '../components/Footer.jsx';
import Reveal, { useInView } from '../components/Reveal.jsx';
import { GarageIllustration } from '../components/Illustrations.jsx';
import '../styles/global.css';
import './about.css';

const VALUES = [
  { tag: 'Value 01', title: 'Curiosity First', body: 'We celebrate questions over answers and reward experimentation, even when the robot falls over.' },
  { tag: 'Value 02', title: 'Every Builder Belongs', body: 'We actively recruit students from underrepresented communities and provide need-based scholarship access to all programs.' },
  { tag: 'Value 03', title: 'Real-World Rigor', body: 'Our curriculum is designed with input from working engineers to ensure students learn skills that matter beyond the competition floor.' },
  { tag: 'Value 04', title: 'Compete with Integrity', body: 'We train champions who win with grace, lose with dignity, and always help a rival team fix their robot before a match.' },
];

const TEAM = [
  { role: 'Director', first: 'Dana', last: 'Reyes', name: 'Dana Reyes — Club Director', body: 'Former aerospace engineer and FRC alumna. Dana founded BoltWorks after seeing too many talented kids without access to quality STEM programs.' },
  { role: 'Build Coach', first: 'Marcus', last: 'Obi', name: 'Marcus Obi — Head Build Coach', body: 'Mechanical engineer with 10 years in robotics manufacturing. Marcus runs the fabrication floor and is famous for his ‘no bad ideas’ brainstorm sessions.' },
  { role: 'Software Lead', first: 'Priya', last: 'Nair', name: 'Priya Nair — Software Lead', body: 'Software developer and CS educator who designed BoltWorks’ three-tier coding curriculum, from Scratch to ROS.' },
  { role: 'Outreach', first: 'Tom', last: 'Callahan', name: 'Tom Callahan — Outreach Coordinator', body: 'Former high school teacher turned STEM advocate. Tom manages school partnerships, scholarship programs, and community demo events.' },
];

const STATS = [
  { value: '8', label: 'Years', desc: 'Of continuous operation and growing community since our founding in 2016' },
  { value: '40%', label: 'Alumni', desc: 'Of our alumni have gone on to pursue STEM degrees or careers' },
  { value: '$85K', label: 'Scholarships', desc: 'In need-based scholarships distributed to members over the past three seasons' },
  { value: '30+', label: 'Mentors', desc: 'Industry mentors and volunteer coaches who donate their time each season' },
];

const CHART = [
  { year: '2016', count: 12 },
  { year: '2017', count: 28 },
  { year: '2018', count: 60 },
  { year: '2019', count: 92 },
  { year: '2020', count: 110 },
  { year: '2021', count: 145 },
  { year: '2022', count: 180 },
  { year: '2023', count: 215 },
  { year: '2024', count: 250 },
];

function AboutPage() {
  return (
    <>
      <Nav active="about" />
      <main>
        {/* ====== PAGE HEADER ====== */}
        <section id="about-section-1" data-section-type="page_header" className="about-header">
          <div className="about-header__megaword" aria-hidden="true">GARAGE</div>
          <div className="container about-header__grid">
            <div className="about-header__copy">
              <span className="eyebrow about-header__eyebrow">Our Story</span>
              <h1 className="about-header__headline">
                <span>Born in a <em>Garage.</em></span>
                <span>Built for the World.</span>
              </h1>
              <p className="about-header__subhead">BoltWorks started with five kids, a pile of spare parts, and an unstoppable idea.</p>
              <p className="about-header__body">What began as an informal weekend tinkering group in 2016 has grown into one of the region’s most celebrated youth robotics clubs — a place where every student, regardless of background or experience, gets a seat at the build table.</p>
            </div>
            <div className="about-header__art" aria-hidden="true">
              <GarageIllustration />
            </div>
          </div>
          <div className="about-header__rule" aria-hidden="true" />
        </section>

        {/* ====== STORY / VALUES ====== */}
        <section id="about-section-2" data-section-type="story_block" className="story-block">
          <div className="container story-block__grid">
            <Reveal className="story-block__copy">
              <span className="eyebrow story-block__eyebrow">Mission &amp; Values</span>
              <h2 className="story-block__headline">We Build More<br />Than Robots</h2>
              <p className="story-block__subhead">Our mission is to spark a lifelong love of engineering in every student who walks through our doors.</p>
              <p className="story-block__body">At BoltWorks, we believe the skills learned on the build floor — problem-solving, collaboration, resilience, and creative thinking — are the same skills that change the world. We don’t just teach robotics. We build the next generation of engineers, innovators, and leaders.</p>
            </Reveal>
            <Reveal className="story-block__values" stagger>
              {VALUES.map((v) => (
                <article key={v.tag} className="value-card">
                  <span className="value-card__top" />
                  <span className="value-card__tag">{v.tag}</span>
                  <h3 className="value-card__title">{v.title}</h3>
                  <p className="value-card__body">{v.body}</p>
                </article>
              ))}
            </Reveal>
          </div>
        </section>

        {/* ====== TEAM GRID ====== */}
        <section id="about-section-3" data-section-type="item_grid" className="team-grid-section">
          <div className="container">
            <Reveal className="team-grid-section__head">
              <span className="eyebrow team-grid-section__eyebrow">The Crew</span>
              <h2 className="team-grid-section__headline">Meet the People<br />Behind the Machines</h2>
              <p className="team-grid-section__subhead">Our coaches, mentors, and staff bring professional engineering experience and genuine enthusiasm to every session.</p>
            </Reveal>
            <Reveal className="team-grid" stagger>
              {TEAM.map((m) => (
                <article key={m.first} className="team-card">
                  <span className="team-card__top" />
                  <span className="team-card__role">{m.role}</span>
                  <h3 className="team-card__name">
                    <span className="team-card__first">{m.first}</span>
                    <span className="team-card__last">{m.last}</span>
                  </h3>
                  <div className="team-card__rule" />
                  <p className="team-card__body">{m.body}</p>
                </article>
              ))}
            </Reveal>
            <Reveal className="team-grid-section__cta">
              <a className="btn btn-primary" href="contact.html">Contact Our Team</a>
            </Reveal>
          </div>
        </section>

        {/* ====== STATS (GRADIENT) ====== */}
        <section id="about-section-4" data-section-type="stats" className="about-stats">
          <div className="container about-stats__grid">
            <Reveal className="about-stats__copy">
              <span className="eyebrow about-stats__eyebrow">Our Impact</span>
              <h2 className="about-stats__headline">Numbers That Tell<br />the Real Story</h2>
              <div className="about-stats__items">
                {STATS.map((s, i) => (
                  <AboutStat key={s.label} value={s.value} label={s.label} desc={s.desc} delay={i * 0.1} />
                ))}
              </div>
            </Reveal>
            <Reveal className="about-stats__chart">
              <span className="eyebrow about-stats__chart-eyebrow">Membership Growth 2016–2024</span>
              <GrowthChart />
            </Reveal>
          </div>
        </section>

        {/* ====== CTA CLOSE ====== */}
        <section id="about-section-5" data-section-type="cta" className="about-cta">
          <div className="about-cta__rule about-cta__rule--top" aria-hidden="true" />
          <Reveal className="about-cta__inner">
            <span className="eyebrow about-cta__eyebrow">Join the Story</span>
            <h2 className="about-cta__headline">The Next Chapter<br />Has Your Name on It</h2>
            <p className="about-cta__subhead">Enrollment opens each August and January. Reach out early — spots go fast.</p>
            <div className="about-cta__buttons">
              <a className="btn btn-primary" href="contact.html">Apply for Membership</a>
              <a className="btn btn-secondary" href="departments.html">See Our Departments</a>
            </div>
          </Reveal>
          <div className="about-cta__rule about-cta__rule--bottom" aria-hidden="true" />
        </section>
      </main>
      <Footer />
    </>
  );
}

function AboutStat({ value, label, desc, delay }) {
  const [ref, inView] = useInView();
  return (
    <div ref={ref} className={`about-stat ${inView ? 'is-visible' : ''}`} style={{ '--delay': `${delay}s` }}>
      <div className="about-stat__rule" />
      <div className="about-stat__numeral">{value}</div>
      <div className="about-stat__label">{label}</div>
      <div className="about-stat__desc">{desc}</div>
    </div>
  );
}

function GrowthChart() {
  const [ref, inView] = useInView();
  const max = Math.max(...CHART.map((c) => c.count));
  return (
    <div ref={ref} className={`growth-chart ${inView ? 'is-visible' : ''}`}>
      {CHART.map((c, i) => {
        const ratio = c.count / max;
        const colors = ['#0D0D0D', '#FF1F8E', '#00E5FF'];
        const color = colors[i % colors.length];
        return (
          <div key={c.year} className="growth-chart__row" style={{ '--bar-delay': `${i * 0.08}s` }}>
            <span className="growth-chart__year">{c.year}</span>
            <div className="growth-chart__track">
              <span
                className="growth-chart__bar anim-bar"
                style={{ '--bar-scale': ratio, background: color }}
              />
              <span className="growth-chart__value">{c.count}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<AboutPage />);

