import React from 'react';
import ReactDOM from 'react-dom/client';
import Nav from '../components/Nav.jsx';
import Footer from '../components/Footer.jsx';
import Reveal, { useInView } from '../components/Reveal.jsx';
import { GarageIllustration } from '../components/Illustrations.jsx';
import '../styles/global.css';
import './about.css';

const VALUES = [
  { tag: 'Value 01', title: 'Curiosity First', body: 'We celebrate questions over answers and reward experimentation, even when the robot falls over.' },
  { tag: 'Value 02', title: 'Every Builder Belongs', body: 'We actively recruit students from underrepresented communities and provide need-based scholarship access to all programs.' },
  { tag: 'Value 03', title: 'Real-World Rigor', body: 'Our curriculum is designed with input from working engineers to ensure students learn skills that matter beyond the competition floor.' },
  { tag: 'Value 04', title: 'Compete with Integrity', body: 'We train champions who win with grace, lose with dignity, and always help a rival team fix their robot before a match.' },
];

const TEAM = [
  { role: 'Director', first: 'Dana', last: 'Reyes', name: 'Dana Reyes — Club Director', body: 'Former aerospace engineer and FRC alumna. Dana founded BoltWorks after seeing too many talented kids without access to quality STEM programs.' },
  { role: 'Build Coach', first: 'Marcus', last: 'Obi', name: 'Marcus Obi — Head Build Coach', body: 'Mechanical engineer with 10 years in robotics manufacturing. Marcus runs the fabrication floor and is famous for his ‘no bad ideas’ brainstorm sessions.' },
  { role: 'Software Lead', first: 'Priya', last: 'Nair', name: 'Priya Nair — Software Lead', body: 'Software developer and CS educator who designed BoltWorks’ three-tier coding curriculum, from Scratch to ROS.' },
  { role: 'Outreach', first: 'Tom', last: 'Callahan', name: 'Tom Callahan — Outreach Coordinator', body: 'Former high school teacher turned STEM advocate. Tom manages school partnerships, scholarship programs, and community demo events.' },
];

const STATS = [
  { value: '8', label: 'Years', desc: 'Of continuous operation and growing community since our founding in 2016' },
  { value: '40%', label: 'Alumni', desc: 'Of our alumni have gone on to pursue STEM degrees or careers' },
  { value: '$85K', label: 'Scholarships', desc: 'In need-based scholarships distributed to members over the past three seasons' },
  { value: '30+', label: 'Mentors', desc: 'Industry mentors and volunteer coaches who donate their time each season' },
];

const CHART = [
  { year: '2016', count: 12 },
  { year: '2017', count: 28 },
  { year: '2018', count: 60 },
  { year: '2019', count: 92 },
  { year: '2020', count: 110 },
  { year: '2021', count: 145 },
  { year: '2022', count: 180 },
  { year: '2023', count: 215 },
  { year: '2024', count: 250 },
];

function AboutPage() {
  return (
    <>
      <Nav active="about" />
      <main>
        {/* ====== PAGE HEADER ====== */}
        <section id="about-section-1" data-section-type="page_header" className="about-header">
          <div className="about-header__megaword" aria-hidden="true">GARAGE</div>
          <div className="container about-header__grid">
            <div className="about-header__copy">
              <span className="eyebrow about-header__eyebrow">Our Story</span>
              <h1 className="about-header__headline">
                <span>Born in a <em>Garage.</em></span>
                <span>Built for the World.</span>
              </h1>
              <p className="about-header__subhead">BoltWorks started with five kids, a pile of spare parts, and an unstoppable idea.</p>
              <p className="about-header__body">What began as an informal weekend tinkering group in 2016 has grown into one of the region’s most celebrated youth robotics clubs — a place where every student, regardless of background or experience, gets a seat at the build table.</p>
            </div>
            <div className="about-header__art" aria-hidden="true">
              <GarageIllustration />
            </div>
          </div>
          <div className="about-header__rule" aria-hidden="true" />
        </section>

        {/* ====== STORY / VALUES ====== */}
        <section id="about-section-2" data-section-type="story_block" className="story-block">
          <div className="container story-block__grid">
            <Reveal className="story-block__copy">
              <span className="eyebrow story-block__eyebrow">Mission &amp; Values</span>
              <h2 className="story-block__headline">We Build More<br />Than Robots</h2>
              <p className="story-block__subhead">Our mission is to spark a lifelong love of engineering in every student who walks through our doors.</p>
              <p className="story-block__body">At BoltWorks, we believe the skills learned on the build floor — problem-solving, collaboration, resilience, and creative thinking — are the same skills that change the world. We don’t just teach robotics. We build the next generation of engineers, innovators, and leaders.</p>
            </Reveal>
            <Reveal className="story-block__values" stagger>
              {VALUES.map((v) => (
                <article key={v.tag} className="value-card">
                  <span className="value-card__top" />
                  <span className="value-card__tag">{v.tag}</span>
                  <h3 className="value-card__title">{v.title}</h3>
                  <p className="value-card__body">{v.body}</p>
                </article>
              ))}
            </Reveal>
          </div>
        </section>

        {/* ====== TEAM GRID ====== */}
        <section id="about-section-3" data-section-type="item_grid" className="team-grid-section">
          <div className="container">
            <Reveal className="team-grid-section__head">
              <span className="eyebrow team-grid-section__eyebrow">The Crew</span>
              <h2 className="team-grid-section__headline">Meet the People<br />Behind the Machines</h2>
              <p className="team-grid-section__subhead">Our coaches, mentors, and staff bring professional engineering experience and genuine enthusiasm to every session.</p>
            </Reveal>
            <Reveal className="team-grid" stagger>
              {TEAM.map((m) => (
                <article key={m.first} className="team-card">
                  <span className="team-card__top" />
                  <span className="team-card__role">{m.role}</span>
                  <h3 className="team-card__name">
                    <span className="team-card__first">{m.first}</span>
                    <span className="team-card__last">{m.last}</span>
                  </h3>
                  <div className="team-card__rule" />
                  <p className="team-card__body">{m.body}</p>
                </article>
              ))}
            </Reveal>
            <Reveal className="team-grid-section__cta">
              <a className="btn btn-primary" href="contact.html">Contact Our Team</a>
            </Reveal>
          </div>
        </section>

        {/* ====== STATS (GRADIENT) ====== */}
        <section id="about-section-4" data-section-type="stats" className="about-stats">
          <div className="container about-stats__grid">
            <Reveal className="about-stats__copy">
              <span className="eyebrow about-stats__eyebrow">Our Impact</span>
              <h2 className="about-stats__headline">Numbers That Tell<br />the Real Story</h2>
              <div className="about-stats__items">
                {STATS.map((s, i) => (
                  <AboutStat key={s.label} value={s.value} label={s.label} desc={s.desc} delay={i * 0.1} />
                ))}
              </div>
            </Reveal>
            <Reveal className="about-stats__chart">
              <span className="eyebrow about-stats__chart-eyebrow">Membership Growth 2016–2024</span>
              <GrowthChart />
            </Reveal>
          </div>
        </section>

        {/* ====== CTA CLOSE ====== */}
        <section id="about-section-5" data-section-type="cta" className="about-cta">
          <div className="about-cta__rule about-cta__rule--top" aria-hidden="true" />
          <Reveal className="about-cta__inner">
            <span className="eyebrow about-cta__eyebrow">Join the Story</span>
            <h2 className="about-cta__headline">The Next Chapter<br />Has Your Name on It</h2>
            <p className="about-cta__subhead">Enrollment opens each August and January. Reach out early — spots go fast.</p>
            <div className="about-cta__buttons">
              <a className="btn btn-primary" href="contact.html">Apply for Membership</a>
              <a className="btn btn-secondary" href="departments.html">See Our Departments</a>
            </div>
          </Reveal>
          <div className="about-cta__rule about-cta__rule--bottom" aria-hidden="true" />
        </section>
      </main>
      <Footer />
    </>
  );
}

function AboutStat({ value, label, desc, delay }) {
  const [ref, inView] = useInView();
  return (
    <div ref={ref} className={`about-stat ${inView ? 'is-visible' : ''}`} style={{ '--delay': `${delay}s` }}>
      <div className="about-stat__rule" />
      <div className="about-stat__numeral">{value}</div>
      <div className="about-stat__label">{label}</div>
      <div className="about-stat__desc">{desc}</div>
    </div>
  );
}

function GrowthChart() {
  const [ref, inView] = useInView();
  const max = Math.max(...CHART.map((c) => c.count));
  return (
    <div ref={ref} className={`growth-chart ${inView ? 'is-visible' : ''}`}>
      {CHART.map((c, i) => {
        const ratio = c.count / max;
        const colors = ['#0D0D0D', '#FF1F8E', '#00E5FF'];
        const color = colors[i % colors.length];
        return (
          <div key={c.year} className="growth-chart__row" style={{ '--bar-delay': `${i * 0.08}s` }}>
            <span className="growth-chart__year">{c.year}</span>
            <div className="growth-chart__track">
              <span
                className="growth-chart__bar anim-bar"
                style={{ '--bar-scale': ratio, background: color }}
              />
              <span className="growth-chart__value">{c.count}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<AboutPage />);

