  line-height: 0.85;
  white-space: nowrap;
  z-index: 1;
  opacity: 0;
  animation: about-mega-in 1.4s cubic-bezier(0.22, 1, 0.36, 1) forwards 0.3s;
  text-shadow: 0 0 60px rgba(255, 230, 0, 0.15);
}

@keyframes about-mega-in {
  0% { opacity: 0; transform: translateY(-50%) rotate(-90deg) translateX(-60px); }
  100% { opacity: 1; transform: translateY(-50%) rotate(-90deg) translateX(0); }
}

.about-header__grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 64px;
  align-items: center;
}

.about-header__copy {
  padding-left: 120px;
}

.about-header__eyebrow {
  color: var(--plasma-magenta);
  margin-bottom: 18px;
  opacity: 0;
  animation: word-reveal 0.7s ease forwards 0.5s;
}

.about-header__headline {
  font-family: var(--font-heading);
  font-size: clamp(40px, 6vw, 80px);
  line-height: 0.95;
  letter-spacing: -0.03em;
  color: var(--crowd-white);
  margin-bottom: 28px;
  text-transform: uppercase;
}

.about-header__headline span {
  display: block;
  opacity: 0;
  transform: translateY(30px);
  animation: word-reveal 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
.about-header__headline span:nth-child(1) { animation-delay: 0.6s; }
.about-header__headline span:nth-child(2) { animation-delay: 0.8s; }

.about-header__headline em {
  font-style: normal;
  color: var(--reactor-yellow);
}

.about-header__subhead {
  font-size: 20px;
  color: var(--poster-cream);
  margin-bottom: 22px;
  opacity: 0;
  animation: word-reveal 0.8s ease forwards 1s;
}

.about-header__body {
  color: var(--poster-cream);
  font-size: 17px;
  max-width: 520px;
  opacity: 0;
  animation: word-reveal 0.8s ease forwards 1.1s;
}

.about-header__art {
  position: relative;
  margin-bottom: -80px;
  z-index: 3;
  opacity: 0;
  animation: word-reveal 1.1s ease forwards 0.7s;
}

.about-header__rule {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--reactor-yellow);
}

/* ====== STORY BLOCK ====== */
.story-block {
  background: var(--backstage-charcoal);
  padding: 140px 0 100px;
}

.story-block__grid {
  display: grid;
  grid-template-columns: 1fr 1.3fr;
  gap: 80px;
  align-items: start;
}

.story-block__copy {
  position: relative;
  padding-right: 32px;
  border-right: 3px solid var(--ignition-orange);
}

.story-block__eyebrow {
  color: var(--ignition-orange);
  margin-bottom: 14px;
}

.story-block__headline {
  font-size: clamp(34px, 4.5vw, 56px);
  color: var(--crowd-white);
  letter-spacing: -0.03em;
  margin-bottom: 16px;
  line-height: 0.95;
}

.story-block__subhead {
  font-size: 18px;
  color: var(--poster-cream);
  margin-bottom: 22px;
}

.story-block__body {
  font-size: 17px;
  color: var(--poster-cream);
  max-width: 380px;
}

.story-block__values {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.value-card {
  position: relative;
  background: var(--voltage-black);
  padding: 22px 22px;
  transition: transform 0.3s ease, background 0.3s ease;
}

.value-card__top {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--plasma-magenta);
  transition: height 0.3s ease;
}

.value-card:hover { transform: translateY(-4px); background: #15151E; }
.value-card:hover .value-card__top { height: 5px; background: var(--reactor-yellow); }

.value-card__tag {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.25em;
  color: var(--circuit-cyan);
  text-transform: uppercase;
  margin-bottom: 10px;
  display: inline-block;
}

.value-card__title {
  font-size: 22px;
  color: var(--crowd-white);
  margin-bottom: 12px;
  letter-spacing: -0.02em;
}

.value-card__body {
  font-size: 15px;
  color: var(--poster-cream);
  line-height: 1.55;
}

/* ====== TEAM GRID ====== */
.team-grid-section {
  background: var(--voltage-black);
  padding: 100px 0;
}

.team-grid-section__head { margin-bottom: 56px; }

.team-grid-section__eyebrow {
  color: var(--circuit-cyan);
  margin-bottom: 14px;
}

.team-grid-section__headline {
  font-size: clamp(34px, 4.2vw, 52px);
  color: var(--crowd-white);
  letter-spacing: -0.03em;
}

.team-grid-section__subhead {
  font-size: 17px;
  color: var(--poster-cream);
  margin-top: 14px;
  max-width: 580px;
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.team-card {
  position: relative;
  background: var(--backstage-charcoal);
  padding: 24px 20px;
  transition: transform 0.3s ease;
  overflow: hidden;
}

.team-card__top {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: var(--ignition-orange);
  transition: background 0.3s ease;
}

.team-card:hover { transform: translateY(-6px); }
.team-card:hover .team-card__top { background: var(--reactor-yellow); }

.team-card__role {
  display: inline-block;
  background: var(--circuit-cyan);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  padding: 4px 10px;
  margin-bottom: 18px;
}

.team-card__name {
  display: flex;
  flex-direction: column;
  font-size: 24px;
  color: var(--crowd-white);
  letter-spacing: -0.02em;
  line-height: 1.05;
  text-transform: uppercase;
}

.team-card__first { display: block; }
.team-card__last { display: block; color: var(--reactor-yellow); }

.team-card__rule {
  height: 1px;
  background: var(--ignition-orange);
  margin: 14px 0 14px;
}

.team-card__body {
  font-size: 15px;
  color: var(--poster-cream);
  line-height: 1.55;
}

.team-grid-section__cta { margin-top: 36px; }

/* ====== STATS (GRADIENT) ====== */
.about-stats {
  background: linear-gradient(135deg, #FF1F8E 0%, #FF5C00 55%, #FFE600 100%);
  padding: 110px 0;
  position: relative;
  overflow: hidden;
}

.about-stats::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 80% 20%, rgba(255, 255, 255, 0.15), transparent 40%);
  pointer-events: none;
}

.about-stats__grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 56px;
  align-items: center;
  position: relative;
}

.about-stats__eyebrow {
  color: var(--voltage-black);
  margin-bottom: 14px;
}

.about-stats__headline {
  font-size: clamp(34px, 4.5vw, 56px);
  color: var(--voltage-black);
  letter-spacing: -0.03em;
  margin-bottom: 40px;
}

.about-stats__items {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}

.about-stat {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.7s ease var(--delay, 0s), transform 0.7s ease var(--delay, 0s);
}

.about-stat.is-visible { opacity: 1; transform: translateY(0); }

.about-stat__rule {
  width: 40px;
  height: 2px;
  background: var(--voltage-black);
  margin-bottom: 12px;
}

.about-stat__numeral {
  font-family: var(--font-heading);
  font-size: clamp(48px, 6vw, 96px);
  color: var(--crowd-white);
  letter-spacing: -0.04em;
  line-height: 1;
  text-shadow: 0 4px 0 var(--voltage-black);
}

.about-stat__label {
  font-family: var(--font-accent);
  font-size: 14px;
  letter-spacing: 0.2em;
  color: var(--voltage-black);
  text-transform: uppercase;
  margin: 8px 0 4px;
}

.about-stat__desc {
  font-size: 14px;
  color: var(--voltage-black);
  line-height: 1.5;
  max-width: 200px;
}

.about-stats__chart {
  background: var(--voltage-black);
  padding: 24px;
  border: 2px solid var(--voltage-black);
}

.about-stats__chart-eyebrow {
  color: var(--reactor-yellow);
  display: block;
  margin-bottom: 16px;
  font-size: 12px;
}

.growth-chart { display: flex; flex-direction: column; gap: 8px; }
.growth-chart__row {
  display: grid;
  grid-template-columns: 60px 1fr;
  align-items: center;
  gap: 12px;
}

.growth-chart__year {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.15em;
  color: var(--poster-cream);
}

.growth-chart__track {
  position: relative;
  height: 22px;
  background: rgba(245, 240, 220, 0.06);
}

.growth-chart__bar {
  display: block;
  height: 100%;
  background: var(--reactor-yellow);
  transform-origin: left center;
  transform: scaleX(0);
}

.growth-chart.is-visible .growth-chart__bar {
  animation: bar-grow 1.2s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  animation-delay: var(--bar-delay, 0s);
}

.growth-chart__value {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--font-heading);
  font-size: 13px;
  color: var(--crowd-white);
}

/* ====== ABOUT CTA CLOSE ====== */
.about-cta {
  background: var(--voltage-black);
  padding: 100px 32px;
  text-align: center;
  position: relative;
}

.about-cta__rule {
  position: absolute;
  left: 0; right: 0;
  height: 2px;
  background: var(--reactor-yellow);
}
.about-cta__rule--top { top: 0; }
.about-cta__rule--bottom { bottom: 0; }

.about-cta__eyebrow { color: var(--plasma-magenta); margin-bottom: 20px; }

.about-cta__headline {
  font-size: clamp(40px, 6vw, 72px);
  color: var(--reactor-yellow);
  letter-spacing: -0.03em;
  max-width: 880px;
  margin: 0 auto;
  line-height: 0.95;
}

.about-cta__subhead {
  font-size: 18px;
  color: var(--poster-cream);
  max-width: 520px;
  margin: 20px auto 36px;
}

.about-cta__buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ====== RESPONSIVE ====== */
@media (max-width: 1100px) {
  .about-header__megaword { font-size: 140px; }
  .about-header__copy { padding-left: 80px; }
  .about-header__grid { grid-template-columns: 1fr; gap: 32px; }
  .about-header__art { max-width: 480px; margin: 0 auto -60px; }
  .story-block__grid { grid-template-columns: 1fr; gap: 40px; }
  .story-block__copy { border-right: none; border-bottom: 3px solid var(--ignition-orange); padding-right: 0; padding-bottom: 32px; }
  .team-grid { grid-template-columns: 1fr 1fr; }
  .about-stats__grid { grid-template-columns: 1fr; }
}

@media (max-width: 720px) {
  .about-header { padding-top: 100px; padding-bottom: 60px; }
  .about-header__megaword { display: none; }
  .about-header__copy { padding-left: 0; }
  .story-block { padding: 80px 0 72px; }
  .story-block__values { grid-template-columns: 1fr; }
  .team-grid { grid-template-columns: 1fr; }
  .about-stats__items { grid-template-columns: 1fr 1fr; gap: 20px; }
}

input.content:
/* ====== DEPARTMENTS PAGE HEADER ====== */
.dep-header {
  background: var(--voltage-black);
  padding: 130px 0 0;
  position: relative;
  overflow: hidden;
}

.dep-header__grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 64px;
  align-items: end;
  padding-bottom: 64px;
}

.dep-header__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  color: var(--reactor-yellow);
  margin-bottom: 22px;
}

.dep-header__eyebrow-rule {
  width: 40px;
  height: 2px;
  background: var(--reactor-yellow);
}

.dep-header__headline {
  font-family: var(--font-heading);
  font-size: clamp(48px, 8vw, 96px);
  line-height: 0.94;
  letter-spacing: -0.035em;
  color: var(--crowd-white);
  text-transform: uppercase;
}

.dep-h-row {
  display: block;
  opacity: 0;
  transform: translateY(36px);
  animation: word-reveal 0.85s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
.dep-h-row:nth-child(1) { animation-delay: 0.2s; }
.dep-h-row:nth-child(2) { animation-delay: 0.4s; }
.dep-h-row:nth-child(3) { animation-delay: 0.6s; }
.dep-h-row--accent { color: var(--reactor-yellow); }

.dep-header__right {
  padding-bottom: 24px;
}

.dep-header__subhead {
  font-size: 18px;
  color: var(--poster-cream);
  margin-bottom: 16px;
}

.dep-header__body {
  font-size: 16px;
  color: var(--poster-cream);
}

.dep-header__icons {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 0;
  border-top: 2px solid var(--ignition-orange);
}

.dep-header__icon {
  width: 100%;
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--backstage-charcoal);
  border-right: 1px solid var(--ignition-orange);
  position: relative;
  opacity: 0;
  transform: translateY(20px);
  animation: word-reveal 0.6s ease forwards;
  animation-delay: var(--icon-delay, 0s);
  transition: background 0.3s ease;
}

.dep-header__icon:last-child { border-right: none; }

.dep-header__icon svg {
  width: 56%;
  height: 56%;
  transition: transform 0.3s ease, color 0.3s ease;
}

.dep-header__icon:hover { background: rgba(255, 230, 0, 0.08); }
.dep-header__icon:hover svg { transform: scale(1.08) rotate(-4deg); }

/* ====== GRID SECTION ====== */
.dep-grid {
  background: var(--voltage-black);
  padding: 80px 0 100px;
  position: relative;
  overflow: hidden;
}

.dep-grid__ghost {
  position: absolute;
  left: 50%;
  top: 60%;
  transform: translate(-50%, -50%);
  font-family: var(--font-accent);
  font-size: clamp(120px, 22vw, 220px);
  color: var(--reactor-yellow);
  opacity: 0.08;
  letter-spacing: 0.02em;
  white-space: nowrap;
  pointer-events: none;
  user-select: none;
  z-index: 0;
}

.dep-grid__inner { position: relative; z-index: 1; }

.dep-grid__head { margin-bottom: 48px; }
.dep-grid__eyebrow { color: var(--reactor-yellow); margin-bottom: 14px; }
.dep-grid__headline {
  font-size: clamp(32px, 5vw, 56px);
  color: var(--crowd-white);
  letter-spacing: -0.03em;
  margin-bottom: 18px;
}
.dep-grid__subhead {
  font-size: 17px;
  color: var(--poster-cream);
  max-width: 600px;
}

.dep-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 40px;
}

.dep-card {
  position: relative;
  padding: 28px 22px;
  transition: transform 0.3s ease;
  overflow: hidden;
}

.dep-card--charcoal { background: var(--backstage-charcoal); }
.dep-card--black { background: var(--voltage-black); border: 1px solid var(--ignition-orange); }

.dep-card__top {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--ignition-orange);
  transition: background 0.3s ease;
}

.dep-card:hover { transform: translateY(-6px); }
.dep-card:hover .dep-card__top { background: var(--reactor-yellow); }
.dep-card:hover .dep-card__icon { transform: rotate(-8deg) scale(1.08); color: var(--reactor-yellow); }

.dep-card__icon {
  width: 44px;
  height: 44px;
  margin-bottom: 16px;
  color: var(--crowd-white);
  transition: transform 0.3s ease, color 0.3s ease;
}

.dep-card__title {
  font-size: 24px;
  color: var(--crowd-white);
  margin-bottom: 12px;
  letter-spacing: -0.02em;
}

.dep-card__body {
  font-size: 15px;
  color: var(--poster-cream);
  line-height: 1.55;
  margin-bottom: 18px;
}

.dep-card__meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.dep-chip {
  background: var(--circuit-cyan);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 6px 10px;
}

/* ====== COMPARISON ====== */
.dep-compare {
  background: linear-gradient(135deg, #FF1F8E 0%, #FF5C00 100%);
  padding: 96px 0;
  position: relative;
  overflow: hidden;
}

.dep-compare::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 80% 30%, rgba(255, 230, 0, 0.18), transparent 50%);
  pointer-events: none;
}

.dep-compare__head { margin-bottom: 48px; position: relative; }
.dep-compare__eyebrow { color: var(--crowd-white); margin-bottom: 14px; }
.dep-compare__headline {
  font-size: clamp(32px, 5vw, 56px);
  color: var(--crowd-white);
  letter-spacing: -0.03em;
}
.dep-compare__subhead {
  font-size: 17px;
  color: rgba(255, 255, 255, 0.92);
  margin-top: 16px;
  max-width: 720px;
}

.dep-tiles {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  position: relative;
  margin-bottom: 32px;
}

.dep-tile {
  background: var(--voltage-black);
  border: 2px solid var(--reactor-yellow);
  display: flex;
  flex-direction: column;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.dep-tile:hover {
  transform: translateY(-6px) rotate(-1deg);
  box-shadow: 0 12px 0 var(--voltage-black);
}

.dep-tile__band {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 22px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-align: center;
  padding: 14px 16px;
}

.dep-tile__body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
}

.dep-tile__age {
  font-family: var(--font-heading);
  font-size: 44px;
  color: var(--reactor-yellow);
  letter-spacing: -0.04em;
  line-height: 1;
}

.dep-tile__title {
  font-size: 20px;
  color: var(--crowd-white);
  letter-spacing: -0.01em;
}

.dep-tile__desc {
  font-size: 14px;
  color: var(--poster-cream);
  line-height: 1.55;
  flex: 1;
}

.dep-tile__meta div { display: flex; gap: 8px; align-items: baseline; margin-bottom: 6px; }
.dep-tile__meta dt {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  color: var(--circuit-cyan);
  text-transform: uppercase;
}
.dep-tile__meta dd { font-size: 13px; color: var(--crowd-white); }

.dep-compare__cta {
  display: flex;
  justify-content: flex-end;
}

.dep-compare__cta .btn {
  background: var(--crowd-white);
  color: var(--voltage-black);
  border-color: var(--crowd-white);
}

.dep-compare__cta .btn:hover {
  background: var(--voltage-black);
  color: var(--crowd-white);
  border-color: var(--voltage-black);
}

/* ====== TESTIMONIALS ====== */
.dep-testi {
  background: var(--backstage-charcoal);
  padding: 110px 0 96px;
  position: relative;
}

.dep-testi__wristband {
  position: absolute;
  top: -60px;
  left: 32px;
  width: 280px;
  z-index: 3;
  transform: rotate(-6deg);
  animation: float-bolt 5s ease-in-out infinite;
}

.dep-testi__head {
  margin-left: 320px;
  margin-bottom: 56px;
}

.dep-testi__eyebrow { color: var(--circuit-cyan); margin-bottom: 14px; }

.dep-testi__headline {
  font-size: clamp(32px, 4.5vw, 52px);
  color: var(--crowd-white);
  letter-spacing: -0.03em;
}

.dep-testi__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  align-items: start;
}

.dep-testi-block {
  position: relative;
  padding-left: 24px;
  border-left: 3px solid var(--ignition-orange);
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.8s ease, transform 0.8s ease;
}

.dep-testi-block.is-visible { opacity: 1; transform: translateY(0); }

.dep-testi-block--0 { grid-row: span 2; margin-top: 32px; }
.dep-testi-block--1 { grid-column: 2; margin-top: 0; }
.dep-testi-block--2 { grid-column: 2; margin-top: 16px; }

.dep-testi-block__quote {
  position: absolute;
  font-family: var(--font-heading);
  font-size: 180px;
  color: rgba(255, 31, 142, 0.2);
  top: -40px;
  left: 0;
  line-height: 1;
  pointer-events: none;
}

.dep-testi-block__division {
  display: inline-block;
  background: var(--circuit-cyan);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.22em;
  padding: 4px 10px;
  margin-bottom: 18px;
}

.dep-testi-block__text {
  font-family: var(--font-heading);
  font-size: 22px;
