  line-height: 1.5;
}

.dep-testi-block__cite {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.18em;
  color: var(--reactor-yellow);
  font-style: normal;
  text-transform: uppercase;
}

/* ====== CTA CLOSE ====== */
.dep-cta {
  background: var(--voltage-black);
  padding: 80px 0;
  position: relative;
}

.dep-cta__eyebrow { color: var(--reactor-yellow); margin-bottom: 24px; display: block; }

.dep-cta__band {
  background: var(--reactor-yellow);
  width: 100vw;
  margin: 40px 0;
  padding: 50px 32px;
  position: relative;
  left: 50%;
  transform: translateX(-50%);
  overflow: hidden;
}

.dep-cta__band::before,
.dep-cta__band::after {
  content: '';
