  top: 0; bottom: 0;
  width: 80px;
  background: repeating-linear-gradient(45deg, var(--voltage-black) 0 8px, transparent 8px 18px);
  opacity: 0.15;
}
.dep-cta__band::before { left: 0; }
.dep-cta__band::after { right: 0; }

.dep-cta__headline {
  font-size: clamp(36px, 5.5vw, 72px);
  letter-spacing: -0.03em;
  color: var(--voltage-black);
