  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 6px 10px;
}

/* ====== COMPARISON ====== */
.dep-compare {
  background: linear-gradient(135deg, #FF1F8E 0%, #FF5C00 100%);
