input.content:
/* ====== RESEARCH HEADER ====== */
.res-header {
  background: var(--voltage-black);
  padding: 130px 0 60px;
  position: relative;
  overflow: hidden;
}

.res-header__grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 56px;
  align-items: center;
  min-height: 60vh;
}

.res-header__eyebrow {
  display: inline-block;
  color: var(--circuit-cyan);
  border: 1px solid var(--circuit-cyan);
  padding: 6px 12px;
  margin-bottom: 24px;
  opacity: 0;
  animation: word-reveal 0.7s ease forwards 0.15s;
}

.res-header__headline {
  font-family: var(--font-heading);
  font-size: clamp(40px, 6.4vw, 80px);
  line-height: 0.96;
  letter-spacing: -0.035em;
  color: var(--crowd-white);
  text-transform: uppercase;
  margin-bottom: 24px;
}

.res-header__headline span {
  display: block;
  opacity: 0;
  transform: translateY(36px);
  animation: word-reveal 0.85s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
.res-header__headline span:nth-child(1) { animation-delay: 0.2s; }
.res-header__headline span:nth-child(2) { animation-delay: 0.4s; }
.res-header__headline span:nth-child(3) { animation-delay: 0.6s; }
.res-header__headline em { color: var(--reactor-yellow); font-style: normal; }

.res-header__subhead {
  font-size: 18px;
  color: var(--poster-cream);
  margin-bottom: 16px;
  max-width: 520px;
  opacity: 0;
  animation: word-reveal 0.7s ease forwards 0.85s;
}

.res-header__body {
  font-size: 16px;
  color: var(--poster-cream);
  opacity: 0.85;
  max-width: 480px;
  opacity: 0;
  animation: word-reveal 0.7s ease forwards 1s;
}

.res-header__art {
  position: relative;
  margin-right: -8%;
  opacity: 0;
  animation: word-reveal 1.2s ease forwards 0.5s;
}

.res-header__rule {
  height: 3px;
  background: var(--ignition-orange);
  margin-top: 40px;
}

/* ====== ARTICLE LIST ====== */
.res-articles {
  background: var(--voltage-black);
  padding: 80px 0;
}

.res-articles__head { margin-bottom: 48px; }
.res-articles__eyebrow { color: var(--ignition-orange); margin-bottom: 14px; }
.res-articles__headline { font-size: clamp(32px, 5vw, 56px); color: var(--crowd-white); }
.res-articles__subhead { font-size: 17px; color: var(--poster-cream); margin-top: 16px; max-width: 600px; }

.res-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-bottom: 48px;
}

.res-cards > :nth-child(5) { grid-column: 1; max-width: 100%; }

.res-card {
  position: relative;
  background: var(--backstage-charcoal);
  padding: 28px;
  transition: background 0.3s ease, transform 0.3s ease;
  overflow: hidden;
}

.res-card__top {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: var(--ignition-orange);
  transition: background 0.3s ease;
}

.res-card:hover { background: #252535; transform: translateY(-4px); }
.res-card:hover .res-card__top { background: var(--reactor-yellow); }

.res-card__title {
  font-size: 22px;
  color: var(--crowd-white);
  letter-spacing: -0.02em;
  margin-bottom: 14px;
}

.res-card__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.res-chip {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  padding: 5px 10px;
  text-transform: uppercase;
  background: var(--circuit-cyan);
  color: var(--voltage-black);
}

.res-chip--completed {
  background: var(--reactor-yellow);
}

.res-card__division {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.2em;
  color: var(--plasma-magenta);
  text-transform: uppercase;
}

.res-card__lead {
  font-size: 13px;
  color: var(--poster-cream);
  opacity: 0.85;
}

.res-card__body {
  font-size: 15px;
  color: var(--poster-cream);
  line-height: 1.6;
}

/* ====== STATS (GRADIENT — SIGNATURE) ====== */
.res-stats {
  background: linear-gradient(135deg, #FF1F8E 0%, #FFE600 100%);
  padding: 80px 0 96px;
  position: relative;
  overflow: hidden;
}

.res-stats::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.18), transparent 40%);
  pointer-events: none;
}

.res-stats__head { position: relative; margin-bottom: 48px; }
.res-stats__eyebrow { color: var(--voltage-black); margin-bottom: 12px; }
.res-stats__headline {
  font-size: clamp(32px, 4.4vw, 52px);
  color: var(--voltage-black);
  letter-spacing: -0.02em;
}

.res-stats__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  position: relative;
  margin-bottom: 56px;
}

.res-stat {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.8s ease var(--delay, 0s), transform 0.8s ease var(--delay, 0s);
}

.res-stat.is-visible { opacity: 1; transform: translateY(0); }

.res-stat__rule {
  display: block;
  width: 40px;
  height: 2px;
  background: var(--voltage-black);
  margin-bottom: 8px;
}

.res-stat__label {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.2em;
  color: var(--voltage-black);
  text-transform: uppercase;
  margin-bottom: 6px;
}

.res-stat__numeral {
  font-family: var(--font-heading);
  font-size: clamp(72px, 9vw, 128px);
  color: var(--crowd-white);
  letter-spacing: -0.04em;
  line-height: 1;
  margin-bottom: 16px;
  text-shadow: 0 6px 0 var(--voltage-black);
}

.res-stat__desc {
  font-size: 14px;
  color: var(--voltage-black);
  line-height: 1.45;
  max-width: 200px;
}

.res-stats__chart {
  background: var(--voltage-black);
  padding: 28px;
  max-width: 720px;
}

.res-stats__chart-eyebrow {
  color: var(--reactor-yellow);
  display: block;
  margin-bottom: 18px;
  font-size: 12px;
}

.dept-bar-chart {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.dept-bar {
  display: grid;
  grid-template-columns: 140px 1fr 40px;
  align-items: center;
  gap: 18px;
}

.dept-bar__label {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.18em;
  color: var(--poster-cream);
}

.dept-bar__track {
  position: relative;
  height: 32px;
  background: rgba(245, 240, 220, 0.08);
}

.dept-bar__fill {
  display: block;
  height: 100%;
  background: var(--reactor-yellow);
  transform-origin: left center;
  transform: scaleX(0);
}

.dept-bar-chart.is-visible .dept-bar__fill {
  animation: bar-grow 1.2s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  animation-delay: var(--bar-delay, 0s);
}

.dept-bar__tick {
  position: absolute;
  right: 6px;
  top: 50%;
  transform: translateY(-50%);
  width: 6px;
  height: 20px;
  background: var(--ignition-orange);
}

.dept-bar__value {
  font-family: var(--font-heading);
  font-size: 18px;
  color: var(--crowd-white);
  text-align: right;
}

/* ====== GALLERY ====== */
.res-gallery {
  background: var(--backstage-charcoal);
  padding: 100px 0;
  position: relative;
}

.res-gallery__head { margin-bottom: 48px; max-width: 680px; }
.res-gallery__eyebrow { color: var(--reactor-yellow); margin-bottom: 14px; }
.res-gallery__headline { font-size: clamp(32px, 5vw, 56px); color: var(--crowd-white); }
.res-gallery__subhead { font-size: 17px; color: var(--poster-cream); margin-top: 16px; }

.res-gallery__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.res-milestone {
  position: relative;
  background: var(--voltage-black);
  border: 1px solid #2A2A3A;
  padding: 56px 28px 28px;
  transition: transform 0.3s ease, border-color 0.3s ease;
}

.res-milestone:hover { transform: translateY(-6px); border-color: var(--reactor-yellow); }
.res-milestone--tall { min-height: 340px; }
.res-milestone--short { min-height: 280px; }

.res-milestone__badge {
  position: absolute;
  top: -32px;
  left: 20px;
  width: 64px;
  height: 64px;
  border-radius: 50%;
