  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 18px;
  letter-spacing: -0.02em;
  box-shadow: 0 0 0 4px var(--backstage-charcoal);
  transition: transform 0.3s ease;
}

.res-milestone:hover .res-milestone__badge { transform: rotate(-8deg) scale(1.06); }

.res-milestone__team {
  display: inline-block;
  background: var(--circuit-cyan);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  padding: 4px 10px;
  margin-bottom: 14px;
}

.res-milestone__title {
  font-size: 20px;
  color: var(--crowd-white);
  letter-spacing: -0.01em;
  line-height: 1.15;
  margin-bottom: 12px;
}

.res-milestone__desc {
  font-size: 15px;
  color: var(--poster-cream);
  line-height: 1.55;
}

.res-gallery__rule {
  height: 3px;
  background: var(--plasma-magenta);
  margin-top: 40px;
}

/* ====== CTA ====== */
.res-cta {
  background: var(--reactor-yellow);
  padding: 100px 32px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.res-cta::before, .res-cta::after {
  content: '';
  position: absolute;
  width: 200px;
  height: 200px;
  border: 4px solid var(--voltage-black);
  opacity: 0.06;
}

.res-cta::before { top: -80px; left: -80px; transform: rotate(45deg); }
.res-cta::after { bottom: -80px; right: -80px; transform: rotate(45deg); }

.res-cta__inner {
  max-width: 760px;
  margin: 0 auto;
  position: relative;
}

.res-cta__eyebrow { color: var(--voltage-black); margin-bottom: 20px; }

.res-cta__headline {
  font-size: clamp(36px, 5.5vw, 72px);
  color: var(--voltage-black);
  letter-spacing: -0.03em;
  line-height: 0.95;
}

.res-cta__headline-accent {
  font-size: 0.85em;
  color: var(--plasma-magenta);
}

.res-cta__subhead {
  font-size: 17px;
  color: var(--voltage-black);
  opacity: 0.85;
  margin: 24px auto 36px;
  max-width: 560px;
}

.res-cta__buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ====== RESPONSIVE ====== */
@media (max-width: 1100px) {
  .res-header__grid { grid-template-columns: 1fr; }
  .res-header__art { max-width: 500px; margin: 0 auto; }
  .res-cards { grid-template-columns: 1fr; }
  .res-cards > :nth-child(5) { grid-column: 1; }
  .res-stats__grid { grid-template-columns: 1fr 1fr; }
  .res-gallery__grid { grid-template-columns: 1fr; }
}

@media (max-width: 720px) {
  .res-stats__grid { grid-template-columns: 1fr; }
  .dept-bar { grid-template-columns: 100px 1fr 36px; gap: 10px; }
}

