/* ====== CONTACT HEADER ====== */
.ct-header {
  background: var(--voltage-black);
  padding: 140px 32px 80px;
  text-align: center;
  position: relative;
  overflow: hidden;
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.ct-header__inner {
  max-width: 920px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.ct-header__eyebrow {
  color: var(--plasma-magenta);
  margin-bottom: 22px;
}

.ct-header__headline {
  font-family: var(--font-heading);
  font-size: clamp(40px, 6vw, 72px);
  letter-spacing: -0.03em;
  line-height: 0.95;
  color: var(--crowd-white);
  text-transform: uppercase;
  margin-bottom: 24px;
}

.ct-header__headline span {
  display: block;
  opacity: 0;
  transform: translateY(36px);
  animation: word-reveal 0.85s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
.ct-header__headline span:nth-child(1) { animation-delay: 0.2s; }
.ct-header__headline span:nth-child(2) { animation-delay: 0.4s; }
.ct-header__headline span:nth-child(3) { animation-delay: 0.6s; }
.ct-header__headline--big {
  color: var(--reactor-yellow);
  font-size: 1.1em;
}

.ct-header__subhead {
  font-size: 18px;
  color: var(--poster-cream);
  max-width: 660px;
  margin: 0 auto;
  opacity: 0;
  animation: word-reveal 0.7s ease forwards 0.9s;
}

.ct-header__art {
  margin-top: 48px;
  max-width: 580px;
  width: 100%;
  opacity: 0;
  animation: word-reveal 1.1s ease forwards 0.6s;
}

/* ====== CONTACT BLOCK ====== */
.ct-block {
  display: grid;
  grid-template-columns: 55% 45%;
  position: relative;
  min-height: 100vh;
}

.ct-block__form-col {
  background: linear-gradient(135deg, #FF1F8E 0%, #FFE600 100%);
  padding: 80px 60px 80px 80px;
  position: relative;
  overflow: hidden;
}

.ct-block__form-col::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 80% 80%, rgba(255, 255, 255, 0.18), transparent 40%);
  pointer-events: none;
}

.ct-block__form-inner {
  position: relative;
  max-width: 720px;
}

.ct-block__eyebrow {
  color: var(--voltage-black);
  margin-bottom: 20px;
}

.ct-block__headline {
  font-family: var(--font-heading);
  font-size: clamp(38px, 5vw, 72px);
  color: var(--reactor-yellow);
  letter-spacing: -0.03em;
  line-height: 0.95;
  text-transform: uppercase;
  margin-bottom: 20px;
  position: relative;
  z-index: 2;
  text-shadow: 0 4px 0 var(--voltage-black);
  white-space: normal;
}

@media (min-width: 1100px) {
  .ct-block__headline {
    width: calc(100% + 120px);
  }
}

.ct-block__subhead {
  font-size: 17px;
  color: var(--voltage-black);
  margin-bottom: 12px;
}

.ct-block__body {
  font-size: 16px;
  color: var(--voltage-black);
  margin-bottom: 32px;
  max-width: 480px;
}

.ct-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
  max-width: 520px;
  position: relative;
  z-index: 1;
}

.ct-form__field {
  display: flex;
  flex-direction: column;
}

.ct-form__field span {
  font-family: var(--font-accent);
  font-size: 12px;
