  text-align: center;
  position: relative;
  overflow: hidden;
  min-height: 60vh;
}

.ct-cta__bolt {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  opacity: 0.18;
  pointer-events: none;
}

.ct-cta__bolt--l {
