const { chromium } = require('/usr/local/lib/node_modules/playwright');

const pages = [
  { url: 'http://127.0.0.1:3001/index.html', slug: 'home', sections: ['home-section-1','home-section-2','home-section-3','home-section-4','home-section-5'] },
  { url: 'http://127.0.0.1:3001/about.html', slug: 'about', sections: ['about-section-1','about-section-2','about-section-3','about-section-4','about-section-5'] },
  { url: 'http://127.0.0.1:3001/departments.html', slug: 'departments', sections: ['departments-section-1','departments-section-2','departments-section-3','departments-section-4','departments-section-5'] },
  { url: 'http://127.0.0.1:3001/research.html', slug: 'research', sections: ['research-section-1','research-section-2','research-section-3','research-section-4','research-section-5'] },
  { url: 'http://127.0.0.1:3001/contact.html', slug: 'contact', sections: ['contact-section-1','contact-section-2','contact-section-3','contact-section-4','contact-section-5'] },
];

(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  for (const p of pages) {
    const page = await ctx.newPage();
    const errors = [];
    page.on('pageerror', (e) => errors.push(e.message));
    page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
    await page.goto(p.url, { waitUntil: 'networkidle' });
    const slug = await page.getAttribute('body', 'data-page-slug');
    const missing = [];
    for (const sid of p.sections) {
      const el = await page.$(`#${sid}`);
      if (!el) { missing.push(sid); continue; }
      const stype = await el.getAttribute('data-section-type');
      if (!stype) missing.push(`${sid} (no data-section-type)`);
    }
    console.log(`${p.slug}: body slug=${slug} | missing: ${missing.length ? missing.join(', ') : 'NONE'} | errors: ${errors.length ? errors.join('; ') : 'NONE'}`);
    await page.close();
  }
  await browser.close();
})();
