/* ====== DEPARTMENTS PAGE HEADER ====== */
.dep-header {
  background: var(--voltage-black);
  padding: 130px 0 0;
  position: relative;
  overflow: hidden;
}

.dep-header__grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 64px;
  align-items: end;
  padding-bottom: 64px;
}

.dep-header__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  color: var(--reactor-yellow);
  margin-bottom: 22px;
}

.dep-header__eyebrow-rule {
  width: 40px;
  height: 2px;
  background: var(--reactor-yellow);
}

.dep-header__headline {
  font-family: var(--font-heading);
  font-size: clamp(48px, 8vw, 96px);
  line-height: 0.94;
  letter-spacing: -0.035em;
  color: var(--crowd-white);
  text-transform: uppercase;
}

.dep-h-row {
  display: block;
  opacity: 0;
  transform: translateY(36px);
  animation: word-reveal 0.85s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
.dep-h-row:nth-child(1) { animation-delay: 0.2s; }
.dep-h-row:nth-child(2) { animation-delay: 0.4s; }
.dep-h-row:nth-child(3) { animation-delay: 0.6s; }
.dep-h-row--accent { color: var(--reactor-yellow); }

.dep-header__right {
  padding-bottom: 24px;
}

.dep-header__subhead {
  font-size: 18px;
  color: var(--poster-cream);
  margin-bottom: 16px;
}

.dep-header__body {
  font-size: 16px;
  color: var(--poster-cream);
}

.dep-header__icons {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 0;
  border-top: 2px solid var(--ignition-orange);
}

.dep-header__icon {
  width: 100%;
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--backstage-charcoal);
  border-right: 1px solid var(--ignition-orange);
  position: relative;
  opacity: 0;
  transform: translateY(20px);
  animation: word-reveal 0.6s ease forwards;
  animation-delay: var(--icon-delay, 0s);
  transition: background 0.3s ease;
}

.dep-header__icon:last-child { border-right: none; }

.dep-header__icon svg {
  width: 56%;
  height: 56%;
  transition: transform 0.3s ease, color 0.3s ease;
}

.dep-header__icon:hover { background: rgba(255, 230, 0, 0.08); }
.dep-header__icon:hover svg { transform: scale(1.08) rotate(-4deg); }

/* ====== GRID SECTION ====== */
.dep-grid {
  background: var(--voltage-black);
  padding: 80px 0 100px;
  position: relative;
  overflow: hidden;
}

.dep-grid__ghost {
  position: absolute;
  left: 50%;
  top: 60%;
  transform: translate(-50%, -50%);
  font-family: var(--font-accent);
  font-size: clamp(120px, 22vw, 220px);
  color: var(--reactor-yellow);
  opacity: 0.08;
  letter-spacing: 0.02em;
  white-space: nowrap;
  pointer-events: none;
  user-select: none;
  z-index: 0;
}

.dep-grid__inner { position: relative; z-index: 1; }

.dep-grid__head { margin-bottom: 48px; }
.dep-grid__eyebrow { color: var(--reactor-yellow); margin-bottom: 14px; }
.dep-grid__headline {
  font-size: clamp(32px, 5vw, 56px);
  color: var(--crowd-white);
  letter-spacing: -0.03em;
  margin-bottom: 18px;
}
.dep-grid__subhead {
  font-size: 17px;
  color: var(--poster-cream);
  max-width: 600px;
}

.dep-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 40px;
}

.dep-card {
  position: relative;
  padding: 28px 22px;
  transition: transform 0.3s ease;
  overflow: hidden;
}

.dep-card--charcoal { background: var(--backstage-charcoal); }
.dep-card--black { background: var(--voltage-black); border: 1px solid var(--ignition-orange); }

.dep-card__top {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--ignition-orange);
  transition: background 0.3s ease;
}

.dep-card:hover { transform: translateY(-6px); }
.dep-card:hover .dep-card__top { background: var(--reactor-yellow); }
.dep-card:hover .dep-card__icon { transform: rotate(-8deg) scale(1.08); color: var(--reactor-yellow); }

.dep-card__icon {
  width: 44px;
  height: 44px;
  margin-bottom: 16px;
  color: var(--crowd-white);
  transition: transform 0.3s ease, color 0.3s ease;
}

.dep-card__title {
  font-size: 24px;
  color: var(--crowd-white);
  margin-bottom: 12px;
  letter-spacing: -0.02em;
}

.dep-card__body {
  font-size: 15px;
  color: var(--poster-cream);
  line-height: 1.55;
  margin-bottom: 18px;
}

.dep-card__meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.dep-chip {
  background: var(--circuit-cyan);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 6px 10px;
}

/* ====== COMPARISON ====== */
.dep-compare {
  background: linear-gradient(135deg, #FF1F8E 0%, #FF5C00 100%);
  padding: 96px 0;
  position: relative;
  overflow: hidden;
}

.dep-compare::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 80% 30%, rgba(255, 230, 0, 0.18), transparent 50%);
  pointer-events: none;
}

.dep-compare__head { margin-bottom: 48px; position: relative; }
.dep-compare__eyebrow { color: var(--crowd-white); margin-bottom: 14px; }
.dep-compare__headline {
  font-size: clamp(32px, 5vw, 56px);
  color: var(--crowd-white);
  letter-spacing: -0.03em;
}
.dep-compare__subhead {
  font-size: 17px;
  color: rgba(255, 255, 255, 0.92);
  margin-top: 16px;
  max-width: 720px;
}

.dep-tiles {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  position: relative;
  margin-bottom: 32px;
}

.dep-tile {
  background: var(--voltage-black);
  border: 2px solid var(--reactor-yellow);
  display: flex;
  flex-direction: column;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.dep-tile:hover {
  transform: translateY(-6px) rotate(-1deg);
  box-shadow: 0 12px 0 var(--voltage-black);
}

.dep-tile__band {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 22px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-align: center;
  padding: 14px 16px;
}

.dep-tile__body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
}

.dep-tile__age {
  font-family: var(--font-heading);
  font-size: 44px;
  color: var(--reactor-yellow);
  letter-spacing: -0.04em;
  line-height: 1;
}

.dep-tile__title {
  font-size: 20px;
  color: var(--crowd-white);
  letter-spacing: -0.01em;
}

.dep-tile__desc {
  font-size: 14px;
  color: var(--poster-cream);
  line-height: 1.55;
  flex: 1;
}

.dep-tile__meta div { display: flex; gap: 8px; align-items: baseline; margin-bottom: 6px; }
.dep-tile__meta dt {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  color: var(--circuit-cyan);
  text-transform: uppercase;
}
.dep-tile__meta dd { font-size: 13px; color: var(--crowd-white); }

.dep-compare__cta {
  display: flex;
  justify-content: flex-end;
}

.dep-compare__cta .btn {
  background: var(--crowd-white);
  color: var(--voltage-black);
  border-color: var(--crowd-white);
}

.dep-compare__cta .btn:hover {
  background: var(--voltage-black);
  color: var(--crowd-white);
  border-color: var(--voltage-black);
}

/* ====== TESTIMONIALS ====== */
.dep-testi {
  background: var(--backstage-charcoal);
  padding: 110px 0 96px;
  position: relative;
}

.dep-testi__wristband {
  position: absolute;
  top: -60px;
  left: 32px;
  width: 280px;
  z-index: 3;
  transform: rotate(-6deg);
  animation: float-bolt 5s ease-in-out infinite;
}

.dep-testi__head {
  margin-left: 320px;
  margin-bottom: 56px;
}

.dep-testi__eyebrow { color: var(--circuit-cyan); margin-bottom: 14px; }

.dep-testi__headline {
  font-size: clamp(32px, 4.5vw, 52px);
  color: var(--crowd-white);
  letter-spacing: -0.03em;
}

.dep-testi__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  align-items: start;
}

.dep-testi-block {
  position: relative;
  padding-left: 24px;
  border-left: 3px solid var(--ignition-orange);
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.8s ease, transform 0.8s ease;
}

.dep-testi-block.is-visible { opacity: 1; transform: translateY(0); }

.dep-testi-block--0 { grid-row: span 2; margin-top: 32px; }
.dep-testi-block--1 { grid-column: 2; margin-top: 0; }
.dep-testi-block--2 { grid-column: 2; margin-top: 16px; }

.dep-testi-block__quote {
  position: absolute;
  font-family: var(--font-heading);
  font-size: 180px;
  color: rgba(255, 31, 142, 0.2);
  top: -40px;
  left: 0;
  line-height: 1;
  pointer-events: none;
}

.dep-testi-block__division {
  display: inline-block;
  background: var(--circuit-cyan);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.22em;
  padding: 4px 10px;
  margin-bottom: 18px;
}

.dep-testi-block__text {
  font-family: var(--font-heading);
  font-size: 22px;
  color: var(--crowd-white);
  letter-spacing: -0.01em;
  line-height: 1.32;
  margin-bottom: 16px;
  text-transform: none;
  font-weight: 900;
}

.dep-testi-block--2 .dep-testi-block__text {
  font-family: var(--font-body);
  font-style: italic;
  font-weight: 400;
  color: var(--poster-cream);
  font-size: 18px;
  line-height: 1.5;
}

.dep-testi-block__cite {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.18em;
  color: var(--reactor-yellow);
  font-style: normal;
  text-transform: uppercase;
}

/* ====== CTA CLOSE ====== */
.dep-cta {
  background: var(--voltage-black);
  padding: 80px 0;
  position: relative;
}

.dep-cta__eyebrow { color: var(--reactor-yellow); margin-bottom: 24px; display: block; }

.dep-cta__band {
  background: var(--reactor-yellow);
  width: 100vw;
  margin: 40px 0;
  padding: 50px 32px;
  position: relative;
  left: 50%;
  transform: translateX(-50%);
  overflow: hidden;
}

.dep-cta__band::before,
.dep-cta__band::after {
  content: '';
  position: absolute;
  top: 0; bottom: 0;
  width: 80px;
  background: repeating-linear-gradient(45deg, var(--voltage-black) 0 8px, transparent 8px 18px);
  opacity: 0.15;
}
.dep-cta__band::before { left: 0; }
.dep-cta__band::after { right: 0; }

.dep-cta__headline {
  font-size: clamp(36px, 5.5vw, 72px);
  letter-spacing: -0.03em;
  color: var(--voltage-black);
  text-align: center;
  line-height: 0.95;
  position: relative;
  z-index: 2;
}

.dep-cta__bottom { padding-top: 24px; }

.dep-cta__subhead {
  font-size: 17px;
  color: var(--poster-cream);
  margin-bottom: 32px;
  max-width: 720px;
}

.dep-cta__buttons {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* ====== RESPONSIVE ====== */
@media (max-width: 1100px) {
  .dep-header__grid { grid-template-columns: 1fr; gap: 32px; }
  .dep-header__right { padding-bottom: 0; }
  .dep-cards { grid-template-columns: 1fr 1fr; }
  .dep-tiles { grid-template-columns: 1fr 1fr; }
  .dep-testi__head { margin-left: 0; padding-top: 240px; }
  .dep-testi__wristband { left: 50%; transform: translateX(-50%) rotate(-6deg); }
  .dep-testi__grid { grid-template-columns: 1fr; gap: 36px; }
  .dep-testi-block--0 { grid-row: auto; margin-top: 0; }
  .dep-testi-block--1, .dep-testi-block--2 { grid-column: 1; }
}

@media (max-width: 720px) {
  .dep-header__icons { grid-template-columns: repeat(3, 1fr); }
  .dep-header__icons .dep-header__icon:nth-child(3) { border-right: none; }
  .dep-cards { grid-template-columns: 1fr; }
  .dep-tiles { grid-template-columns: 1fr; }
  .dep-cta__band { padding: 40px 20px; }
}

